const HISTORICAL_RECORDS={18:{id:'treaty',name:'서로 다른 협정문',text:'제국의 승전 기록에는 평화협정 하루 전 노크스가 전사했다. 그늘의 사절 기록에는 그가 협정 당일 살아서 입장했다고 적혀 있다.'},38:{id:'assassination',name:'세라디온의 봉인 명령',text:'협상단의 호위를 해제하라. 노크스가 자리를 떠나기 전에 빛의 이름으로 협정을 끝내라. 왕좌는 이후 진실의 은폐를 승인했다.'},52:{id:'cycle',name:'태양의 원래 호흡',text:'나무의 빛은 자라나고 잦아들었다. 엘리온의 왕좌가 이 주기를 멈추고 영원한 낮을 뽑아내자 뿌리가 안에서부터 탔다.'},67:{id:'legacyLink',name:'검과 검집의 문양',text:'레온의 검은 노크스의 검집과 맞는다. 원래의 수호 유물은 한 군주의 무기가 아니라 서로의 힘을 제한하는 한 쌍이었다.'}};
const SCENES={
 1:{title:'태양 아래, 두 사람',lines:[['아렌','태양의 기사들처럼 그림자를 몰아내면, 우리 같은 아이들은 더는 고향을 잃지 않을 거야.'],['루네','나도 함께 갈게. 네 검이 닿지 않는 이름은 내가 기억할 테니까.'],['어린 아렌','넌 왜 항상 어두운 하늘만 보는 거야? 태양이 훨씬 밝잖아.'],['어린 루네','별이 있으니까. 태양이 너무 밝으면 별이 안 보이잖아.']]},
 27:{title:'빈자리',lines:[['아렌','루네? 장난이지? 네 수첩도… 한 장이 없어.'],['아렌','그림자가 데려간 거야. 반드시 찾아올게.']]},
 40:{title:'협정의 밤',lines:[['직조자의 기억','노크스는 더 죽이지 않기 위해 협상장으로 갔다. 세라디온은 그 평화를 함정으로 바꾸었다.'],['아렌','그렇다면 우리가 배운 승리는… 무엇을 숨기고 있었던 거지?'],['루네의 남은 쪽지','그늘의 저항에는 이유가 있어. 하지만 이유가 있다고 모든 폭력이 옳아지는 것은 아니야.']]},
 58:{title:'별을 남기는 사람',lines:[['루네','어둠은 별을 집어삼키는 악마가 아니었어. 다른 별들이 빛날 자리를 남기려 했던 거야.'],['루네','하지만 우리도 다른 사람의 빛을 가리고 있었는지도 몰라. 내가 도운 작전의 피해자들을 잊지 마.'],['루네','그러니까 내가 옳았다고만 생각하지 마. 네가 직접 보고, 직접 선택해.'],['아렌','돌아와, 루네. 이 검집과 수첩만 남기지 말고…'],['서술','루네는 마지막 피난민을 통로 밖으로 밀어냈다. 꺼진 별의 검집과 수첩이 아렌에게 남았다.']]},
 60:{title:'아버지의 이름',lines:[['노크스의 기억','나는 그늘을 지켰다. 그러나 승리를 위해 비운 마을에서는 돌아오지 못한 사람들이 있었다.'],['노크스의 기억','아렌. 내 아들이라는 사실은 내 모든 판단을 따르라는 뜻이 아니다.'],['아렌','아버지의 검을 쥐어도, 선택은 내 것이어야 해.']]},
 66:{title:'영원한 서광',lines:[['레온','어릴 때 난 항상 너한테 졌지. 널 이길 만큼 강해지면 너희 둘을 지킬 수 있다고 생각했어.'],['레온','그런데 정작 무엇을 지키려 했는지 잊었더라. 국민을 지키는 마음과 국가의 명령이 같은 것은 아니었어.'],['레온','이 검은 태양을 위해 바쳐졌지만… 내가 처음 검을 든 이유는 누군가를 지키고 싶어서였어. 받아 줘.'],['세라디온','꺼져 가는 빛은 영원한 빛이 아니다.'],['서술','갈라진 황금빛이 레온의 실루엣을 감쌌다. 그의 검만은 사라지지 않았다.'],['아렌','네가 지키려던 사람들을, 내가 잊지 않을게.']]},
 69:{title:'스스로 삼킨 빛',lines:[['세라디온','노크스의 아들… 나는 누구보다 태양을 섬겼다! 이 빛은 나를 선택했어야 한다!'],['세라디온','내가 영원한 빛이 될 것이다!'],['서술','태양의 갑옷이 갈라졌다. 보호를 위해 만들어진 유물은 끝없는 권능을 담지 못했다.'],['아렌','꺼져 가는 사람을 버린 네가, 빛까지 혼자 가지려 했구나.']]},
 70:{title:'왕좌의 이유',lines:[['엘리온','내가 왕좌에서 내려오면 이 제국은 무너질 것이다. 식량도, 방어도, 빛의 도관도.'],['아렌','그래서 다른 나라의 자유를 빼앗았습니까? 진실을 알고도 숨겼습니까?'],['엘리온','그 책임은 나의 것이다. 하지만 자유만으로 전쟁을 막을 수 있느냐?'],['아렌','혼란을 두려워한다는 이유로, 다른 사람의 선택까지 빼앗을 수는 없습니다.']]}
};
const NPC_LINES={
 5:['레온','이번엔 내가 이길지도 몰라. 정식 기사가 되면 너희 둘부터 지킬 거야.'],12:['태양의 순례자','태양의 물길이 끊겼을 때 우리 아이가 아팠어요. 빛이 돌아와 살아났지요.'],16:['퇴역 플레어 기사','국경을 지킨 명령과 마을을 비우라는 명령이 같은 봉인으로 왔지. 난 후자도 따랐다.'],23:['레온','이 갑옷은 사람들을 구한 뒤 받았어. 제국을 믿는 이유는 책에만 있지 않아.'],28:['그늘의 연락책','납치라니. 루네는 스스로 왔다. 네가 매복으로 들어가는 길부터 끊으러 갔어.'],31:['늙은 역사가','구원자의 이름 옆에 침략자의 이름을 적어 보게. 같은 얼굴이 나타날 수도 있지.'],32:['그늘의 난민','저 검문 문장은 우리 집을 불태운 군복에도 있었어요. 저쪽 농부가 같은 일을 겪지 않았으면 해요.'],35:['루네','이 문 너머에는 네 유물을 노린 매복이 있어. 널 가두려는 게 아니라, 네가 살아서 보길 바랐어. 난 스스로 그늘에 왔어.'],36:['그늘의 온건파','제국에 맞선다는 이유로 아이들이 탄 수레를 불태울 수는 없어. 모르반에게도 그렇게 말했다.'],45:['모르반','제국이 사라진 자리에 질서가 저절로 생길까? 이번에는 우리가 하나의 왕좌가 되어야 한다.'],48:['제국의 농부','태양이 사라질까 두려웠는데, 이제는 너무 오래 빛나서 밭이 타. 어느 쪽 말도 쉽게 믿기 어렵네.'],54:['루네','평화를 위해 싸웠어. 그렇다고 내가 택한 모든 방법이 정당해지는 것은 아니야. 그 책임을 피하지 않을게.'],55:['피난민','루네가 도운 작전에서 내 형제가 다쳤어. 오늘 이 길을 열어 주었다고 그 일이 지워지지는 않아.'],62:['태양의 순례자','국경에서 다시 만났네요. 빛이 우리 아이를 살린 일과 나라가 저지른 일을 함께 기억해 주세요.']
};
const RELIC_HISTORY={blade:['칼리아 · 고대림의 검객','제국 기록은 개척 영웅이라 부른다. 숲의 마을은 그 검이 지킨 피난로를 기억한다.'],ember:['메이라 · 불씨의 의사','불로 성채를 태운 자이자 겨울의 야전 병원을 데운 자. 같은 불의 다른 기록이 남았다.'],frost:['이스렌 · 북부 독립국의 창병','후퇴하던 병사들을 위해 다리를 얼렸다. 적의 추격뿐 아니라 이웃의 길도 함께 끊었다.'],storm:['세일 · 국경의 사수','보급 수레를 지킨 화살은 반대편 마을에서는 식량을 빼앗은 화살로 기록되었다.'],reaper:['베른 · 이름 없는 장례병','싸움을 끝낸 낫이 아니라 돌아오지 못한 사람들의 이름을 모은 낫이었다.'],warden:['오룸 · 나무의 수호자','왕도와 숲 사이에서 방패를 들었다. 어느 명령에도 방패 뒤의 사람을 넘기지 않으려 했다.'],nox:['노크스 · 어둠의 기사','그늘의 독립을 지키다 평화협정에서 암살당했다. 아렌의 아버지. 그의 실수까지 함께 기억해야 한다.'],aren:['아렌 · 아직 쓰이지 않은 역사','어떤 영웅의 유산도 다음 사람의 판단까지 대신할 수 없다.']};


