function openScene(stage){const key='scene'+stage,s=ensureStory();if(!SCENES[stage]||s.seen.includes(key)||sessionSeen.has(key))return false;sessionSeen.add(key);s.seen.push(key);storyView={kind:'scene',stage,index:0,scene:SCENES[stage]};mode='story';screen('story');renderStory();return true;}
function preJourneyOpenNPC(n){if(n.record){const d=HISTORICAL_RECORDS[n.record],s=ensureStory();if(!s.clues.includes(d.id))s.clues.push(d.id);storyView={kind:'talk',speaker:'기록 · '+d.name,text:d.text};}
 else if(n.choice){const chosen=run.story.choices[n.choice];storyView=chosen?{kind:'talk',speaker:n.speaker,text:'이 길에서 당신은 '+chosen.label+'를 선택했다. '+choiceConsequence(chosen.kind)}:{kind:'choice',stage:n.choice,data:CHOICES[n.choice]};}
 else if(n.gift){if(!run.artifacts.includes(n.gift)){level.chest={x:n.x-23,y:(n.routeFloor??FLOOR)-38,w:46,h:38,opened:true,claimed:false,artifact:n.gift};toast('꺼진 별의 유물 · V 2초 획득 / 1·2 칸 선택');n.hidden=true;return;}storyView={kind:'talk',speaker:n.speaker,text:n.text};}
 else{let text=n.text;if(n.id==='talk62'&&run.story.choices[7]?.kind==='freedom')text+=' 그때 국경의 배급이 줄었던 일도 기억해요.';storyView={kind:'talk',speaker:n.speaker,text};}mode='story';screen('story');renderStory();}
function advanceStory(){if(mode!=='story'||!storyView)return;if(revealDialogue())return;if(storyView.kind==='choice'||storyView.kind==='ending')return;if(storyView.kind==='scene'&&++storyView.index<storyView.scene.lines.length){renderStory();return;}skipStory();}
function skipStory(){if(mode!=='story')return;storyView=null;dialogueState=null;mode='playing';screen(null);canvas.focus({preventScroll:true});updateHUD();}
function chooseStory(index){if(mode!=='story'||storyView?.kind!=='choice')return false;const stage=storyView.stage,data=storyView.data,option=data.options[index],s=ensureStory();if(!option||s.choices[stage])return false;const[label,delta,kind]=option;s.choices[stage]={index,label,kind};s.alignment=clamp(s.alignment+delta,0,100);if(kind==='civic')s.civic++;s.flags.lastSupport=kind;skipStory();voice(data.speaker,choiceConsequence(kind),5);return true;}
function choiceConsequence(kind){return kind==='order'?'다음 길에서 공식 지원으로 에너지를 조금 얻는다. 보호가 명령에 기대어 있다는 사실도 남는다.':kind==='freedom'?'그늘의 해방을 우선했다. 지원은 길을 열지만 반대편 사람들의 손실까지 지우지는 못한다.':'민간인을 먼저 지켰다. 다음 교전에서 작은 수호막을 얻고, 어느 편의 정답도 대신 받아들이지 않는다.';}
function moonEligible(){const s=ensureStory();return s.alignment>=30&&s.alignment<=70&&s.civic>=3&&['treaty','assassination','cycle','legacyLink'].every(k=>s.clues.includes(k))&&s.flags.notebookDecoded&&['notebook','scabbard','eternalDawn'].every(k=>s.keys.includes(k));}
function chooseEnding(which){const s=ensureStory();if(run.stage!==70||!s.elionDefeated||s.branch||!['dark','light','moon'].includes(which)||which==='moon'&&!moonEligible()||which==='dark'&&s.alignment>65||which==='light'&&s.alignment<35)return false;s.branch=which;if(which==='dark'){finishEnding('dark');return true;}run.hp=Math.max(1,p.hp);run.energy=p.energy;entry=clone(run);if(!practice)persistCheckpoint();beginBranch(which);return true;}
function beginBranch(which){const def=BRANCH_BOSSES[which];if(!def)return;shots=[];zones=[];telegraphs=[];level.endingAltars=[];level.storyClearDone=false;level.bossWarning=null;level.bossEvents=[];for(const e of level.enemies)e.dead=true;const s=level.sectors.at(-1);s.cleared=false;s.spawned=false;s.kind='boss';level.bossDef=def;level.boss=null;level.rewardSpawned=false;level.portalOpen=false;level.activeSector=s.index;spawnSector(level,s.index);p.inv=2;p.hp=Math.min(maxHP(),p.hp+25);p.energy=Math.max(60,p.energy);p.x=level.bossOrigin+250;p.y=562;voice(def.name,def.quote,6);}
function finishEnding(which){const s=ensureStory();s.ending=which;s.endingComplete=true;run.cleared=70;run.stage=70;run.hp=Math.max(1,p.hp);run.energy=p.energy;if(!practice){recordCurrentStage();unlocked=70;persistCheckpoint();persistRecords();}mode='ending';screen('ending');const texts={dark:['검은 왕관','태양의 나무가 쓰러지고 빛의 지배가 끝났다. 아렌은 어둠의 왕좌에 올랐다. 새로운 질서는 곧 새로운 책임이 되었다.\n빛이 사라진 하늘에 작은 별들이 드러났다. 완벽한 어둠도, 영원한 왕관도 없었다.'],light:['마지막 씨앗','모르반의 불을 막은 아렌은 태양의 나무를 지켰다. 그러나 전쟁으로 황폐해진 땅이 곧바로 되살아나지는 않았다.\n그는 레온의 검과 루네의 수첩을 내려놓고 작은 씨앗을 심었다. 빛은 그 가능성을 비추었다.'],moon:['왕관 없는 세계','왕좌의 모방을 깨뜨린 검과 검집은 빛을 독점하던 도관을 끊었다. 태양의 나무는 자연의 주기를 되찾고 처음으로 달이 떴다.\n갈등은 끝나지 않았다. 이제 사람들은 한 명의 군주 대신 서로에게 선택의 책임을 물어야 했다.']};$('ending-title').textContent=texts[which][0];$('ending-prose').textContent=texts[which][1];$('ending-stats').innerHTML=`<div class="stat"><strong>${fmt(run.time)}</strong><span>여정의 시간</span></div><div class="stat"><strong>${s.alignment}</strong><span>빛 / 어둠 · 선악 수치 아님</span></div><div class="stat"><strong>${Object.keys(s.choices).length}/7</strong><span>남긴 선택</span></div>`;}
function sagaStoryStep(dt){if(level.endingAltars?.length&&pressed.has('interact')){const a=level.endingAltars.find(a=>Math.abs(p.x+15-a.x)<72);if(a){pressed.delete('interact');if(a.id==='moon'&&!moonEligible()){voice('수첩의 빈자리','네 핵심 기록, 해독된 수첩, 두 유산, 민간인을 지킨 판단과 중간 성향이 필요하다.',5);}else{storyView={kind:'ending',ending:a.id};mode='story';screen('story');renderStory();}return;}}
 if(run.stage<=3&&run.stage!==1&&level.time>5&&!level.luneHint&&level.enemies.some(e=>!e.dead)){level.luneHint=true;voice('루네',level.sectors[level.activeSector].kind==='seal'?'결계 심장부터! 저 빛이 남아 있는 동안 다른 적도 보호받아.':'원거리 적의 준비선을 봐. 그리고 적을 정리한 뒤 다음 길로 가자.',4);}
}
function preJourneyUpdateStoryHUD(){if(!level?.route)return;const s=level.sectors[level.activeSector];$('stage-name').textContent=level.route.name+' · '+s.location.name;$('narrative-line').textContent=s.kind==='boss'?'':level.story||level.route.story;$('narrative-line').style.visibility=s.kind==='boss'?'hidden':'visible';const st=ensureStory();$('alignment-hud').textContent=`어둠 ${100-st.alignment} ◇ 빛 ${st.alignment} · 선택 ${Object.keys(st.choices).length}/7`;$('alignment-hud').title='해방·독립과 질서·안정 사이의 선택. 선악 점수가 아닙니다.';}



