const dialoguePortraitCache=[],DIALOGUE_CAST=[{name:'루네',role:'별을 기록하는 사람',color:'#b5cbd6'},{name:'레온',role:'플레어 기사',color:'#e5c58c'},{name:'세라디온',role:'태양의 대사제',color:'#e4c271'},{name:'엘리온',role:'태양의 왕',color:'#d8b86b'},{name:'노크스',role:'꺼진 별의 기사',color:'#a9c6d4'},{name:'아렌',role:'아직 쓰이지 않은 역사',color:'#e0b783'}];
function knownPortrait(name){if(typeof name!=='string')return null;return name.includes('루네')?0:name.includes('레온')?1:name.includes('세라디온')?2:name.includes('엘리온')?3:name.includes('노크스')?4:name.includes('아렌')?5:null;}
function dialoguePortrait(index){if(index===null)return null;if(dialoguePortraitCache[index])return dialoguePortraitCache[index];if(!dialogueImage.complete||!dialogueImage.naturalWidth)return null;const w=Math.floor(dialogueImage.naturalWidth/3),h=Math.floor(dialogueImage.naturalHeight/2),c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');g.drawImage(dialogueImage,index%3*w,Math.floor(index/3)*h,w,h,0,0,w,h);const d=g.getImageData(0,0,w,h);for(let k=3;k<d.data.length;k+=4)d.data[k]=d.data[k]<145?0:255;g.putImageData(d,0,0);return dialoguePortraitCache[index]={url:c.toDataURL(),image:c};}
function setDialogueActor(side,index,active,name){const holder=$('story-actor-'+side),img=$(side==='left'?'story-portrait':'story-listener'),f=dialoguePortrait(index);holder.classList.toggle('speaking',active);holder.classList.toggle('unseen',index===null);holder.style.setProperty('--portrait-color',index===null?'#baa875':DIALOGUE_CAST[index].color);holder.querySelector('.actor-caption').textContent=name||'';if(f){if(img.getAttribute('src')!==f.url)img.src=f.url;img.alt=name||'';img.style.visibility='visible';}else{img.removeAttribute('src');img.style.visibility='hidden';}}
function preVisiblePresentDialogue(title,speaker,text,buttons,progress=''){const index=knownPortrait(speaker),v=storyView,sceneOther=v?.scene?.lines.map(([n])=>knownPortrait(n)).find(i=>i!==null&&i!==5),right=index!==null&&index!==5?index:sceneOther??(v?.kind==='scene'&&v.stage===1?0:null);const root=$('story');root.style.setProperty('--speaker-color',index===null?'#c5b48b':DIALOGUE_CAST[index].color);root.classList.toggle('narration',index===null);setDialogueActor('left',5,index===5,'아렌');setDialogueActor('right',right,index!==null&&index!==5,right===null?speaker:DIALOGUE_CAST[right].name);$('story-title').textContent=title;$('story-speaker').textContent=speaker;$('story-role').textContent=index===null?'남겨진 이야기':DIALOGUE_CAST[index].role;$('story-text').textContent='';$('story-progress').textContent=progress;$('story-actions').innerHTML=buttons;root.dataset.line=String(++dialogueSerial);root.classList.remove('line-enter');void root.offsetWidth;root.classList.add('line-enter');dialogueState={text:Array.from(text),shown:0,clock:0,pause:0,ready:false,progress};updateDialoguePrompt();}
function updateDialoguePrompt(){const b=document.querySelector('[data-story-next]');if(b)b.textContent=dialogueState?.ready?'다음 · V / Space':'대사 펼치기 · V / Space';$('story-progress').textContent=(dialogueState?.progress||'')+(dialogueState?.ready?'':' · 대사 표시 중');}
function revealDialogue(){if(!dialogueState||dialogueState.ready)return false;dialogueState.shown=dialogueState.text.length;dialogueState.ready=true;$('story-text').textContent=dialogueState.text.join('');updateDialoguePrompt();return true;}
function dialogueClock(dt){const d=dialogueState;if(mode!=='story'||!d||d.ready)return;d.clock+=dt;let changed=false;while(d.shown<d.text.length&&d.clock>=.024+d.pause){d.clock-=.024+d.pause;const c=d.text[d.shown++];d.pause=/[.!?…]/.test(c)?.12:/[,，]/.test(c)?.05:0;changed=true;}if(changed)$('story-text').textContent=d.text.slice(0,d.shown).join('');if(d.shown>=d.text.length){d.ready=true;updateDialoguePrompt();}}
function initDialogueUI(){$('story-text').addEventListener('click',advanceStory);dialogueImage.addEventListener('load',()=>{if(mode==='story'&&storyView){const shown=dialogueState?.shown||0,ready=dialogueState?.ready;renderStory();if(ready)revealDialogue();else if(dialogueState){dialogueState.shown=Math.min(shown,dialogueState.text.length);$('story-text').textContent=dialogueState.text.slice(0,shown).join('');}}});}
function renderCombatVoice(speaker,text){const node=$('voice-line'),index=knownPortrait(speaker),f=dialoguePortrait(index);node.replaceChildren();node.classList.toggle('has-portrait',!!f);if(f){const img=document.createElement('img');img.src=f.url;img.alt='';node.append(img);}const copy=document.createElement('div'),name=document.createElement('strong'),line=document.createElement('span');name.textContent=speaker;line.textContent=text;copy.append(name,line);node.append(copy);}

const itemModelCache=new Map(),FOOD_INFO={soup:{name:'숲버섯 수프',desc:'현재 체력 45 회복.'},meal:{name:'든든한 여행자 정식',desc:'최대 체력 +8, 체력 30 회복. 식사 성장 최대 5회.'},elixir:{name:'별이슬 차',desc:'에너지 100 회복, 스킬과 마법 대기시간 초기화.'}},MARKET_NAMES={weapon:'길손의 무기고',armor:'수피와 강철',ring:'달빛의 고리',aux:'기묘한 보물들',mask:'영웅의 유산',food:'따뜻한 한 끼',evolution:'별을 벼리는 화로'};
const marketVendorCache=[];
function marketVendorFrame(index){if(marketVendorCache[index])return marketVendorCache[index];if(!marketVendorImage.complete||!marketVendorImage.naturalWidth)return null;const w=Math.floor(marketVendorImage.naturalWidth/2),h=Math.floor(marketVendorImage.naturalHeight/2),c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');g.drawImage(marketVendorImage,index%2*w,Math.floor(index/2)*h,w,h,0,0,w,h);const d=g.getImageData(0,0,w,h);let x0=w,y0=h,x1=0,y1=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const k=(y*w+x)*4;if(d.data[k+3]<145)d.data[k+3]=0;else{d.data[k+3]=255;x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);}}g.putImageData(d,0,0);const out=document.createElement('canvas');out.width=Math.max(1,x1-x0+1);out.height=Math.max(1,y1-y0+1);out.getContext('2d').drawImage(c,x0,y0,out.width,out.height,0,0,out.width,out.height);return marketVendorCache[index]={image:out,ratio:out.width/out.height};}
function drawMarketVendor(index,x,y){const f=marketVendorFrame(index);if(!f)return;const h=index===0?175:index===1?160:150,w=h*f.ratio;ctx.save();ctx.imageSmoothingEnabled=false;ctx.drawImage(f.image,Math.round(x-w/2),Math.round(y-h),w,h);ctx.restore();}
function itemModel(id){if(itemModelCache.has(id))return itemModelCache.get(id);const at=ITEM_ART_MAP[id];if(!at)return null;const im=itemArtImages[at.pack];if(!im?.complete||!im.naturalWidth)return null;const cols=at.cols||6,rows=at.rows||4,rect=at.pack==='legacies'?(at.index<8?[at.index%4*350,Math.floor(at.index/4)*285,350,285]:at.index<12?[[0,575,430,265],[430,575,270,265],[700,575,350,265],[1050,575,352,265]][at.index-8]:[(at.index-12)*350,840,350,282]):[at.index%cols*Math.floor(im.naturalWidth/cols),Math.floor(at.index/cols)*Math.floor(im.naturalHeight/rows),Math.floor(im.naturalWidth/cols),Math.floor(im.naturalHeight/rows)],cw=rect[2],ch=rect[3],c=document.createElement('canvas');c.width=cw;c.height=ch;const g=c.getContext('2d');g.drawImage(im,...rect,0,0,cw,ch);const pixels=g.getImageData(0,0,cw,ch);let x0=cw,y0=ch,x1=-1,y1=-1,count=0;for(let y=0;y<ch;y++)for(let x=0;x<cw;x++){const k=(y*cw+x)*4;if(pixels.data[k+3]<145)pixels.data[k+3]=0;else{pixels.data[k+3]=255;x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);count++;}}g.putImageData(pixels,0,0);if(x1<0)return null;const out=document.createElement('canvas');out.width=x1-x0+1;out.height=y1-y0+1;out.getContext('2d').drawImage(c,x0,y0,out.width,out.height,0,0,out.width,out.height);const f={image:out,url:out.toDataURL(),ratio:out.width/out.height,pixels:count};itemModelCache.set(id,f);return f;}
function itemImage(id,extra=''){const f=itemModel(id);return `<img class="item-model ${extra}" data-item-model="${id}" ${f?`src="${f.url}"`:''} alt="${ITEMS[id]?.name||FOOD_INFO[id.split(':')[1]]?.name||'유물 이미지'}" loading="eager">`;}
function drawItemModel(id,x,y,size=64,alpha=1){const f=itemModel(id);if(!f)return;const w=f.ratio>=1?size:size*f.ratio,h=f.ratio>=1?size/f.ratio:size;ctx.save();ctx.globalAlpha=alpha;ctx.imageSmoothingEnabled=false;ctx.drawImage(f.image,Math.round(x-w/2),Math.round(y-h/2),w,h);ctx.restore();}
function initItemModels(){for(const im of Object.values(itemArtImages))im.addEventListener('load',()=>{if(mode==='loadout')renderLedger();if(mode==='merchant')renderMerchant();});}
function itemCard(a){const h=ITEMS[a.id],rarity=RARITY[h.rarity],equipped=Object.entries(run.equipment).find(([k,v])=>v===a.uid),slots=h.slot==='aux'?['aux1','aux2','aux3']:h.slot==='ring'?['ring1','ring2']:[h.slot],safe=equipmentSafe(),old=run.inventory.find(i=>i.uid===run.equipment[slots[0]]),current=old&&ITEMS[old.id],dp=(h.power||0)-(current?.power||0),dh=(h.hp||0)-(current?.hp||0);return `<div class="ledger-card modeled-card ${equipped?'equipped':''}" style="--rarity:${rarity[1]}"><div class="item-showcase">${itemImage(a.id)}</div><span class="tag">${rarity[0]} · ${{weapon:'무기',armor:'갑옷',ring:'반지',aux:'자동 보조'}[h.slot]}</span><h3>${h.name}</h3><p>${h.desc}</p>${h.tags?.length?`<div class="item-tags">${h.tags.map(t=>`<span>${SYNERGIES[t]?.name||{air:'공중',combo:'연격',heavy:'강타',arcane:'비전',explorer:'탐험'}[t]||t}</span>`).join('')}</div>`:''}<div class="item-compare">${current?'현재 '+current.name+' 대비':'빈 칸 대비'} · 위력 ${dp>=0?'+':''}${dp} · 체력 ${dh>=0?'+':''}${dh}</div>${equipped?'<span class="tag">'+SLOT_NAMES[equipped[0]]+' 착용 중</span>':slots.map(slot=>`<button data-equip="${a.uid}" data-slot="${slot}" ${safe?'':'disabled'}>${SLOT_NAMES[slot]} 장착</button>`).join('')}<button data-sell="${a.uid}" ${equipped||h.bound||!safe?'disabled':''}>${h.bound?'중요 유산':level.shop?'판매 '+Math.floor(h.price*.35)+' G':'버리기'}</button></div>`;}
function preFinalConfigureMarket(l){const order=['weapon','armor','ring','aux','mask','food','evolution'];l.products=[];l.marketGroups=[];l.shops=[];let cursor=330;for(const category of order){const start=cursor,offers=category==='evolution'?[{kind:'evolution',id:'evolution',price:0}]:l.stock[category]||[];for(let index=0;index<offers.length;index++){const offer=offers[index];l.products.push({category,index,offer,x:cursor,y:FLOOR-80,token:'market:'+category+':'+index});cursor+=174;}l.marketGroups.push({category,start:start-90,end:cursor-70,center:(start+cursor-174)/2});l.shops.push({category,x:(start+cursor-174)/2,y:FLOOR-70});cursor+=130;}l.width=Math.max(2580,cursor+260);l.portal.x=l.width-145;l.memory.x=l.width-280;l.sectors[0].end=l.width;l.plats[0].w=l.width;l.routeGroups[0].end=l.width;l.props=[];l.signs=[{x:110,y:350,text:'진열품 앞에서 V 구매 · 유물 V 2초 · B 직접 장착 · Space / ↑ 점프 · C 패링'}];}
function preFinalPositionMarketNPCs(l){if(!l.shop)return;for(const n of l.npcs){if(n.gift)n.x=l.width-390;else if(n.id.startsWith('merchantTalk')){n.x=l.marketGroups[0].end-48;n.marketVendor=true;}}}
function preJourneyProductInfo(product){const o=product.offer;if(o.kind==='item'){const h=ITEMS[o.id];return{name:h.name,desc:h.desc,key:o.id,rarity:h.rarity,price:o.price,sold:!!o.sold,kind:'장비'};}if(o.kind==='mask'){const h=FORMS[o.id];return{name:h.name+'의 유물',desc:h.passive||h.desc,key:'mask:'+o.id,rarity:2,price:o.price,sold:!!o.sold,kind:'변신 유물'};}if(o.kind==='food')return{...FOOD_INFO[o.id],key:'food:'+o.id,rarity:0,price:o.price,sold:!!o.sold,kind:'음식'};return{name:run.evolution?'현재 유물 진화 완료':FORMS[run.mask].name+' 진화',desc:EVOLUTIONS[run.mask].basic+' '+EVOLUTIONS[run.mask].s1,key:'utility:evolution',rarity:3,price:evolutionCost(),sold:!!run.evolution,kind:'진화 장인'};}
function pickupSlot(){return run.artifacts.length<2?run.artifacts.length:clamp(p.chestSlot??run.artifacts.indexOf(run.mask),0,1);}
function canHoldPickup(){return mode==='playing'&&held.has('interact')&&p.dash<=0&&p.attack<=0&&p.hurt<=0&&!p.holdLatch;}
function holdPickup(token,source,dt,complete){p.holdTouched=true;for(let i=0;i<2;i++)if(pressed.has('equip'+(i+1)))p.chestSlot=i;const slot=pickupSlot();if(!canHoldPickup()){p.pickupHold=null;return;}if(!p.pickupHold||p.pickupHold.token!==token||p.pickupHold.slot!==slot)p.pickupHold={token,source,slot,progress:0};p.pickupHold.progress=Math.min(2,p.pickupHold.progress+dt);if(p.pickupHold.progress>=2-1e-8){p.pickupAuthorization=source;const ok=complete(slot);p.pickupAuthorization=null;p.pickupHold=null;if(ok!==false)p.holdLatch=true;}}
function preJourneyRevealArtifact(c=level.chest){if(!c||c.claimed||c.opened)return false;c.opened=true;burst(c.x+23,c.y,'#ffe5a0',100);audio.sfx('clear');toast(FORMS[c.artifact].name+' 유물 · V를 2초간 눌러 획득 · 1/2 교체 칸');return true;}
function openArtifact(){const c=level.chest;if(mode!=='playing'||!c||c.claimed)return;if(!c.opened)revealArtifact(c);else toast('V를 2초간 누르면 '+FORMS[c.artifact].name+' 유물을 장착합니다.');}
function preStarterEquipHead(id,slot){const c=level.chest;if(mode!=='playing'||!c?.opened||c.claimed||c.artifact!==id||p.pickupAuthorization!==c)return false;if(replaceMask(id,slot)){c.claimed=true;return true;}return false;}
function preJourneyOpenTreasure(c){if(!c||c.opened)return false;c.opened=true;scatterCoins(c.x+20,FLOOR-35,c.coins);gainXP(18);if(level.lootRandom()<.3)dropGear(c.x+20,FLOOR-48,1);audio.sfx('clear');burst(c.x+20,FLOOR-35,'#efd28a',85);return true;}
function strikeContainers(box){if(!level||mode!=='playing')return;for(const c of level.treasures||[])if(!c.opened&&overlap(box,c))openTreasure(c);const c=level.chest;if(c&&!c.opened&&!c.claimed&&overlap(box,c))revealArtifact(c);}
function preFinalPurchaseOffer(product,fromCatalogue=false){if(!level?.shop||!['playing','merchant'].includes(mode))return false;const o=product?.offer;if(!o)return false;if(o.kind==='evolution')return evolveMask();const info=productInfo(product);if(o.sold)return false;if(o.kind==='mask'&&p.pickupAuthorization!==product){if(fromCatalogue)toast('진열된 유물 앞에서 V를 2초간 누르세요.');return false;}if(run.coins<o.price){toast('골드 부족 · '+(o.price-run.coins)+' G 더 필요');return false;}if(o.kind==='item'&&run.inventory.length>=BAG_CAPACITY){toast('가방이 가득 찼습니다.');return false;}if(o.id==='meal'&&run.food>=5){toast('식사 성장 한도에 도달했습니다.');return false;}if(o.kind==='mask'&&run.artifacts.includes(o.id)){toast('이미 보유한 유물입니다.');return false;}run.coins-=o.price;if(o.kind==='mask'){if(!replaceMask(o.id,pickupSlot())){run.coins+=o.price;return false;}}else if(o.kind==='item')addItem(o.id);else if(o.id==='soup')heal(45);else if(o.id==='meal'){run.food++;heal(30);}else if(o.id==='elixir'){p.energy=100;p.skill1CD=0;p.skill2CD=0;p.skill3CD=Math.max(0,(p.skill3CD||0)-12);p.magicCD=0;}o.sold=true;burst(product.x,FLOOR-100,RARITY[info.rarity][1],90);audio.sfx('select');toast(info.name+' 구매'+(o.kind==='item'?' · B에서 직접 장착':''));if(mode==='merchant')renderMerchant();updateHUD();return true;}
function buyOffer(index){const product=level.products?.find(a=>a.category===merchantCategory&&a.index===index);return purchaseOffer(product,true);}
function preJourneyEvolveMask(){if(!(mode==='playing'&&level.focusProduct?.offer.kind==='evolution'||mode==='merchant'&&merchantCategory==='evolution')||run.evolution||run.coins<evolutionCost())return false;run.coins-=evolutionCost();run.evolution=1;run.formEvolution[run.mask]=1;run.evoMask=run.mask;p.energy=100;burst(p.x+15,p.y+24,maskColor(),200);audio.sfx('ultimate');toast(EVOLUTIONS[run.mask].name+' 진화 · 모든 전투 기술에 새 특성');if(mode==='merchant')renderMerchant();updateHUD();return true;}
function preJourneyEconomyStep(dt){p.maskHint=Math.max(0,(p.maskHint||0)-dt);const center=p.x+15,nearFloor=Math.abs(p.y+p.h-FLOOR)<100;for(const a of level.loot||[])if(!a.got&&Math.abs(a.x-center)<45&&Math.abs(a.y-p.y-24)<80){a.got=true;addItem(a.id);burst(a.x,a.y,RARITY[ITEMS[a.id].rarity][1],65);}level.focusProduct=null;if(!nearFloor)return;const artifact=level.chest&&!level.chest.claimed&&Math.abs(level.chest.x+23-center)<75;if(artifact)return;const nearest=(level.treasures||[]).find(c=>!c.opened&&Math.abs(c.x+20-center)<62);if(nearest&&pressed.has('interact')){openTreasure(nearest);pressed.delete('interact');return;}if(!level.shop)return;const product=level.products?.filter(a=>Math.abs(a.x-center)<76).sort((a,b)=>Math.abs(a.x-center)-Math.abs(b.x-center))[0];level.focusProduct=product||null;if(!product)return;const info=productInfo(product);if(product.offer.kind==='mask'&&!info.sold){if(run.coins>=info.price)holdPickup(product.token,product,dt,()=>purchaseOffer(product));if(pressed.has('interact')){pressed.delete('interact');if(run.coins<info.price)toast('골드 부족 · '+(info.price-run.coins)+' G 더 필요');}}else if(pressed.has('interact')){pressed.delete('interact');purchaseOffer(product);}}
function preJourneyWorldRewardStep(dt,oldX=p.x,oldY=p.y){p.holdTouched=false;if(!held.has('interact'))p.holdLatch=false;for(const o of level.rewardOrbs||[])if(!o.got){const lo=Math.min(oldX,p.x)-25,hi=Math.max(oldX,p.x)+p.w+25;if(o.x>lo&&o.x<hi&&Math.abs(p.y+p.h-o.y)<80){o.got=true;if(o.kind==='heal')heal(o.value);if(o.kind==='energy')p.energy=Math.min(100,p.energy+o.value);if(o.kind==='coins'){run.coins+=o.value;level.collected+=o.value;}spark(o.x,o.y,o.color,12,130);audio.sfx('coin');}}
 economyStep(dt);const c=level.chest,near=c&&!c.claimed&&Math.abs(c.x+23-p.x-15)<75&&Math.abs(p.y+p.h-FLOOR)<95;level.focusReward=null;if(near){level.focusReward={kind:'artifact',x:c.x+23,y:c.y,value:c};if(pressed.has('interact')){if(!c.opened)revealArtifact(c);pressed.delete('interact');}if(c.opened)holdPickup('chest:'+c.x+':'+c.artifact,c,dt,slot=>equipHead(c.artifact,slot));}
 else{const a=!level.rewardClaimed&&(level.inscriptions||[]).filter(a=>Math.abs(a.x-p.x-15)<62&&Math.abs(p.y+p.h-FLOOR)<95).sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x))[0];if(a){level.focusReward={kind:'inscription',x:a.x,y:a.y,value:a};if(run.relics.length>=6)for(let i=0;i<6;i++)if(pressed.has('equip'+(i+1)))p.relicSlot=i;if(pressed.has('interact')){if(!hasRelic(a.id)){if(run.relics.length>=6)run.relics[clamp(p.relicSlot||0,0,5)]=a.id;else run.relics.push(a.id);level.rewardClaimed=true;a.claimed=true;burst(a.x,a.y,maskColor(),95);audio.sfx('select');toast('각인 장착 · '+RELICS[a.id].name);}pressed.delete('interact');}}}
 if(!p.holdTouched)p.pickupHold=null;const n=level.npcs?.filter(n=>!n.hidden&&(n.sector===undefined||n.sector<=level.activeSector)&&(!n.afterClear||level.sectors[n.sector??level.activeSector]?.cleared)).filter(n=>Math.abs(p.x+15-n.x)<64&&Math.abs(p.y+p.h-FLOOR)<95).sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x))[0];level.focusNPC=n||null;if(n&&pressed.has('interact')&&!level.focusProduct&&!near){pressed.delete('interact');openNPC(n);}}
function openMerchant(category){if(!level.shop||mode!=='playing')return;merchantCategory=category;mode='merchant';screen('merchant');renderMerchant();}
