function preJourneyDrawEconomyWorld(){ctx.save();for(const c of level.treasures||[]){if(c.x<camera.x-70||c.x>camera.x+W+70)continue;drawItemModel(c.opened?'utility:chestOpen':'utility:chestClosed',c.x+20,c.y+c.h/2,66);if(!c.opened&&Math.abs(p.x-c.x)<100){ctx.font='700 11px WildrootUI';ctx.textAlign='center';ctx.fillStyle='#ffe6a6';ctx.fillText('Z 공격 / V · 골드 상자',c.x+20,c.y-23);}}for(const a of level.loot||[]){if(a.got||a.x<camera.x-70||a.x>camera.x+W+70)continue;const h=ITEMS[a.id],color=RARITY[h.rarity][1],y=a.y+Math.sin(visualTime*3+a.x)*3;glow(a.x,y,48,color,.17);drawItemModel(a.id,a.x,y,48);ctx.font='700 10px WildrootUI';ctx.textAlign='center';ctx.fillStyle=color;ctx.fillText(h.name,a.x,y-36);}for(const a of level.products||[]){if(a.x<camera.x-150||a.x>camera.x+W+150)continue;const h=productInfo(a),focused=level.focusProduct===a;drawPedestal(a.x,focused);if(!h.sold){const y=FLOOR-98+Math.sin(visualTime*2+a.x)*3;glow(a.x,y,focused?75:45,RARITY[h.rarity][1],focused?.16:.06);drawItemModel(h.key,a.x,y,a.offer.kind==='item'&&ITEMS[a.offer.id].slot==='weapon'?82:70);}else{ctx.font='700 13px WildrootUI';ctx.fillStyle='#a49875';ctx.textAlign='center';ctx.fillText('품절',a.x,FLOOR-94);}rr(a.x-49,FLOOR-35,98,23,1,'#253c2b','#b29961');ctx.textAlign='center';ctx.font='700 13px WildrootUI';ctx.fillStyle=h.sold?'#8e9c7d':run.coins<h.price?'#d69f89':'#e6cb83';ctx.fillText(h.sold?'구매 완료':'● '+h.price,a.x,FLOOR-19);}ctx.restore();}
