function preFinalDrawModelTooltip(info,x,y,action,hold=null){const w=344,h=206;x=clamp(x-w/2,camera.x+18,camera.x+W-w-18);ctx.save();rr(x,y,w,h,2,'#e4d7b7f7','#6d5c3c');pixelRect(x+1,y+1,w-2,5,RARITY[info.rarity??1][1]);drawItemModel(info.key,x+40,y+43,54);ctx.textAlign='left';ctx.font='700 15px WildrootUI';ctx.fillStyle='#332e25';ctx.fillText(info.name,x+77,y+30);ctx.font='10px WildrootUI';ctx.fillStyle='#776646';ctx.fillText((info.kind||'유물')+' · '+RARITY[info.rarity??1][0],x+78,y+50);ctx.font='11px WildrootUI';ctx.fillStyle='#4d4838';wrapRewardText(info.desc||'',x+16,y+82,w-32,17);ctx.fillStyle='#344934';ctx.font='700 12px WildrootUI';ctx.fillText(action,x+16,y+h-35);if(hold){pixelRect(x+16,y+h-21,w-32,7,'#a69d7d');pixelRect(x+16,y+h-21,(w-32)*hold.progress/2,7,'#487955');}else{ctx.font='10px WildrootUI';ctx.fillStyle='#7b7053';ctx.fillText(/변신|가면/.test(info.kind)?'1 / 2 · 교체 칸 선택, 기존 가면 분해':'B · 가방에서 그림과 효과 확인',x+16,y+h-16);}ctx.restore();}
