function cleanSpriteComponents(d,w,h){const seen=new Uint8Array(w*h),components=[];for(let start=0;start<w*h;start++){if(seen[start]||d.data[start*4+3]===0)continue;const queue=[start];seen[start]=1;for(let n=0;n<queue.length;n++){const v=queue[n],x=v%w;for(const q of [x>0?v-1:-1,x<w-1?v+1:-1,v>=w?v-w:-1,v<w*(h-1)?v+w:-1])if(q>=0&&!seen[q]&&d.data[q*4+3]>0){seen[q]=1;queue.push(q);}}components.push(queue);}const max=Math.max(1,...components.map(c=>c.length));for(const c of components)if(c.length<max*.018)for(const v of c)d.data[v*4+3]=0;}
