function maskState(){if(!p.legacy||p.legacy.id!==run.mask)p.legacy={id:run.mask,resource:run.mask==='rider'?20:run.mask==='engineer'?2:0,allies:[],events:[],fx:[],links:[],serial:0,rideTick:0,anchor:null};return p.legacy;}
function liveTargets(x=p.x+15,r=900){return level.enemies.filter(e=>!e.dead&&e.type!=='echo'&&e.sector===level.activeSector&&Math.abs(e.x+e.w/2-x)<r);}
function legacyVisual(kind,x,y,r=90,life=.55,extra={}){maskState().fx.push({owner:run.mask,role:fxRole||'basic',tier:maskTier(),batch:fxBatch||++fxSerial,kind,x,y,r,life,max:life,color:maskColor(),dir:p.dir,...extra});}
function maskEvent(delay,x,y,r,mul,kind='pulse',extra={}){maskState().events.push({role:fxRole||'skill1',tier:maskTier(),batch:fxBatch||++fxSerial,damageType:currentDamageType(),delay,x,y,r,damage:damage()*mul,kind,owner:run.mask,...extra});legacyVisual('warning',x,y,r,Math.max(.1,delay),{color:maskColor()});}
function ally(kind,x=p.x+15,options={}){const s=maskState(),cap=run.mask==='mirror'?3:run.mask==='necro'?6:7;if(s.allies.length>=cap)s.allies.shift();const a={damageType:options.template?enemyDamageType(options.template,true):ALLY_DAMAGE[kind]||currentDamageType(),batch:fxBatch||++fxSerial,role:fxRole||'skill1',kind,x,y:playerCombatFloor(),life:12+(run.evolution?5:0),tick:.3,dir:p.dir,phase:s.serial++*1.8,power:1,sector:level.activeSector,...options};s.allies.push(a);legacyVisual('summon',x,playerCombatFloor()-30,60,.55);audio.sfx('select');return a;}
function maskMelee(x,y,r,mul=1,kind='sword'){strikeContainers({x:x-r,y:y-r,w:r*2,h:r*2});for(const e of liveTargets(x,r+80))if(Math.hypot(e.x+e.w/2-x,e.y+e.h/2-y)<r+e.w*.3)hitEnemy(e,damage()*mul,Math.sign(e.x-x)||p.dir,false,kind);}
function newMaskAttack(){const h=FORMS[run.mask],s=maskState(),id=run.mask;p.combo=p.comboLife>0?(p.combo+1)%h.chain:0;p.comboLife=1;p.swingLength=h.duration[p.combo];p.attack=p.swingLength;p.attackCD=h.period[p.combo]*(1-(run.training?.haste||0)*.04);p.swingDir=p.dir;p.isFinisher=p.combo===h.chain-1;p.attackCharge=0;p.hitIDs.clear();p.finisherFired=false;p.basicShots++;p.vx+=p.dir*h.steps[p.combo];audio.swing(p.isFinisher);legacyVisual('slash',p.x+15,p.y+25,h.ranges[p.combo]||72,p.swingLength,{combo:p.combo});
 if(['necro','chrono','engineer'].includes(id)){const element=id==='necro'?'shadow':id==='chrono'?'wind':'lightning';projectile({vx:p.dir*(id==='engineer'?900:590),vy:0,w:id==='engineer'?24:26,h:id==='engineer'?8:24,damage:damage()*h.multipliers[p.combo],element,basic:true,pierce:p.isFinisher?2:0,returning:id==='necro'&&p.isFinisher&&!!run.evolution,life:1.6,legacyArt:id});if(run.evolution&&id==='engineer'&&p.isFinisher)for(const v of[-110,110])projectile({vx:p.dir*830,vy:v,damage:damage()*.45,element:'lightning',basic:true,w:20,h:8,legacyArt:id});if(id==='chrono'&&p.isFinisher)maskEvent(.65,p.x+15+p.dir*230,p.y+24,95,run.evolution?1.2:.65,'clock');}
 if(id==='mirror')for(const a of s.allies.filter(a=>a.kind==='mirror')){a.dir=p.dir;a.attackPulse=.3;maskEvent(.12,a.x+p.dir*65,a.y-28,90,run.evolution?.7:.45,'mirror');}
 if(p.isFinisher&&run.evolution){if(id==='rider')projectile({vx:p.dir*750,y:playerCombatFloor()-36,w:45,h:45,damage:damage(),pierce:5,element:'fire',skill:true,legacyArt:'wheel'});if(id==='tide')projectile({vx:p.dir*540,w:55,h:42,damage:damage()*.8,pierce:5,element:'ice',returning:true,skill:true});if(id==='beast')maskEvent(.2,p.x+15+p.dir*100,p.y+24,130,.7,'beast');if(id==='puppet')for(const e of s.links.filter(e=>!e.dead))maskEvent(.2,e.x+e.w/2,e.y+e.h/2,48,.5,'thread');if(id==='mirror')maskEvent(.25,p.x+15+p.dir*70,p.y+24,110,.55,'mirror');}
}
function newMaskResolve(dt){if(p.attack<=0)return;p.attack=Math.max(0,p.attack-dt);if(['necro','chrono','engineer'].includes(run.mask))return;const h=FORMS[run.mask],progress=1-p.attack/p.swingLength;if(progress<.27)return;const r=h.ranges[p.combo],box={x:p.swingDir>0?p.x+5:p.x+25-r,y:p.y-20,w:r,h:105};strikeContainers(box);for(const e of liveTargets(p.x+15,r+80))if(!p.hitIDs.has(e)&&overlap(box,e)){p.hitIDs.add(e);hitEnemy(e,damage()*h.multipliers[p.combo],p.swingDir,false,p.isFinisher?'finisher':'sword');if(run.mask==='tide')e.slow=Math.max(e.slow,.5);}}
