 if(id==='beast'){if(slot===1){const alpha=s.resource>=100;if(alpha)s.resource=0;for(let i=0;i<(ev?2:1);i++)ally('wolf',x+d*(40+i*45),{power:alpha?1.5:1,life:alpha?20:ev?17:12,alpha});}else for(let i=0;i<(ev?3:2);i++)ally('wisp',x,{orbit:true,power:ev?1.15:1});}
 if(id==='rider'){if(slot===1){const fuel=s.resource>=25;if(fuel)s.resource-=25;s.nitro=(fuel?.82:.4)+(ev?.2:0);s.rideTick=0;p.rushTime=s.nitro;p.rushSpeed=d*(fuel?1050:790);p.rushKind='bike';p.inv=Math.max(p.inv,.18);legacyVisual('road',x,playerCombatFloor(),300,.8);}else{p.rushTime=0;s.nitro=0;p.vx=-d*330;p.vy=-180;p.ground=false;maskMelee(x,y,185,1.9,'skill');legacyVisual('wheel',x,y,175,.6);if(ev)for(const q of[-1,1])maskEvent(.28,x+q*130,playerCombatFloor()-25,100,.7,'wheel');}}
