 if(!level.focusProduct){const c=level.chest,nearMask=c&&(!level.interactionFocus||level.interactionFocus.value===c)&&!c.claimed&&Math.abs(c.x+23-p.x-15)<76&&Math.abs(p.y+p.h-(c.y+38))<95;if(nearMask){level.focusReward={kind:'artifact',x:c.x+23,y:c.y,value:c};if(pressed.has('interact')){pressed.delete('interact');if(!c.opened)revealArtifact(c);}if(c.opened&&!c.claimed)holdPickup('chest:'+c.x+':'+c.artifact,c,dt,slot=>equipHead(c.artifact,slot));}else{
 const a=level.loot.filter(a=>(!level.interactionFocus||level.interactionFocus.value===a)&&!a.got&&Math.abs(a.x-p.x-15)<64&&Math.abs(a.y-p.y-24)<100).sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x))[0];if(a){level.focusLoot=a;if(pressed.has('interact')){pressed.delete('interact');{const item=addItem(a.id);if(item){a.got=true;acquireFX(ITEMS[a.id].rarity,a.x,a.y);toast(ITEMS[a.id].name+' 획득 · B에서 장착');}}}}else{const c=level.treasures.find(c=>(!level.interactionFocus||level.interactionFocus.value===c)&&!c.opened&&Math.abs(c.x+21-p.x-15)<65&&Math.abs(p.y+p.h-(c.y+c.h))<90);if(c){level.focusTreasure=c;if(pressed.has('interact')){pressed.delete('interact');openTreasure(c);}}else{const n=level.npcs.filter(n=>(!level.interactionFocus||level.interactionFocus.value===n)&&!n.hidden&&!n.rescued&&(n.sector??0)<=level.activeSector&&(!n.afterClear||level.sectors[n.sector??level.activeSector]?.cleared)&&Math.abs(n.x-p.x-15)<66&&Math.abs(p.y+p.h-(n.y??FLOOR))<95).sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x))[0];if(n){level.focusNPC=n;if(pressed.has('interact')){pressed.delete('interact');openNPC(n);}}}}}}
