function initJourney34UI(){document.querySelector('[data-journey-tab=mask]').textContent='가면·진화';$('ledger-content').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.inspect){selectedBagUID=+b.dataset.inspect;renderLedger();}if(b.dataset.dismantle)dismantleItem(+b.dataset.dismantle);if(b.dataset.shatter!==undefined)shatterMask(+b.dataset.shatter);if(b.dataset.bookSection){journalSection=b.dataset.bookSection;journalPage=0;renderLedger();}if(b.dataset.bookTurn){journalPage+=+b.dataset.bookTurn;renderLedger();}if(b.dataset.retrieve&&equipmentSafe()&&run.inventory.length<BAG_CAPACITY){const a=run.overflow.find(a=>a.uid===+b.dataset.retrieve);if(a){run.overflow=run.overflow.filter(b=>b.uid!==a.uid);run.inventory.push(a);selectedBagUID=a.uid;renderLedger();}}});window.addEventListener('keydown',e=>{if(mode==='loadout'&&ledgerTab==='journal'&&['ArrowLeft','ArrowRight'].includes(e.code)){e.preventDefault();e.stopImmediatePropagation();const n=journalEntries().length;journalPage=clamp(journalPage+(e.code==='ArrowRight'?1:-1),0,Math.max(0,n-1));renderLedger();}},true);}

