function drawSkillVisual(a){const t=1-a.life/a.max;let x=a.follow?p.x+15+a.dir*(a.role==='ultimate'?0:48):a.x,y=a.follow?p.y+24:a.y,r=a.r;if(a.projectile){const list=shots.filter(s=>s.friendly&&s.batch===a.batch&&s.life>0);if(list.length){x=list.reduce((n,s)=>n+s.x,0)/list.length;y=list.reduce((n,s)=>n+s.y,0)/list.length;r=a.role==='ultimate'?240:155;}else{a.life=Math.min(a.life,.15);}}naturalSkill(a.family,a.role,x,y,r,t,a.dir,a.tier,.9);}
function naturalBasicFrame(id){return atlasCell(naturalImages.basics,Math.max(0,NATURAL_BASIC_IDS.indexOf(id)),4,4,'natural-basic:'+id);}
function preMotionNaturalSkillFrame(id,role){const a=NATURAL_SKILLS[id]||NATURAL_SKILLS.aren,row=role==='ultimate'?2:id==='rider'?role==='skill2'?0:1:role==='skill2'?1:0;return atlasCell(naturalImages[a[0]],row*4+a[1],4,3,'natural-skill:'+id+':'+row);}
function naturalSprite(f,x,y,w,dir=1,rotation=0,alpha=1,stretch=1){if(!f)return false;paintedFXDraws++;ctx.save();ctx.imageSmoothingEnabled=false;ctx.translate(x,y);ctx.scale(dir,stretch);ctx.rotate(rotation);ctx.globalAlpha*=alpha;ctx.drawImage(f.image,-w/2,-w/f.ratio/2,w,w/f.ratio);ctx.restore();return true;}
