function naturalSkill(id,role,x,y,r,t,dir=1,tier=maskTier(),alpha=1){if(role==='basic')return naturalSprite(naturalBasicFrame(id),x,y,naturalRoleSize(role,r,tier),dir,0,alpha*.72);const f=naturalSkillFrame(id,role);if(!f)return false;const q=clamp(t,0,1),grow=q<.23?.55+.45*(1-Math.pow(1-q/.23,3)):1,fade=q>.72?(1-q)/.28:1,size=naturalRoleSize(role,r,tier);ctx.save();ctx.translate(x,y);ctx.scale(dir,1);ctx.globalAlpha*=Math.max(0,alpha*fade)*(tier===1?.8:tier===2?.9:1);const w=size*grow,h=w/f.ratio,flow=role==='skill1'?1:0;if(flow){const progress=clamp(q/.25,0,1);ctx.beginPath();ctx.rect(-size*.55,-h,Math.max(1,size*(.35+progress*.8)),h*2);ctx.clip();}paintedFXDraws++;ctx.imageSmoothingEnabled=false;ctx.drawImage(f.image,-w/2,-h/2,w,h);ctx.restore();return true;}
function preMotionDrawBladeTrail(id,t,tier){const f=naturalBasicFrame(id);if(!f||t<.1||t>.85)return;const h=FORMS[id],scythe=id==='reaper',r=scythe?91:58+(tier-1)*7,phase=p.combo%2?2.1-t*3.8:-2+t*4,end=phase-Math.PI/2,sign=p.combo%2?-1:1,span=[.56,.73,.92][tier-1],start=end-sign*span,width=[5,8,12][tier-1];ctx.save();ctx.translate(p.x+15+p.dir*14,p.y+p.h-25);ctx.scale(p.swingDir||p.dir,1);ctx.beginPath();ctx.arc(0,0,r+width,start,end,sign<0);ctx.arc(0,0,r-width,end,start,sign>0);ctx.closePath();ctx.clip();ctx.rotate(end-1.15);ctx.globalAlpha=tier===1?.72:.9;ctx.imageSmoothingEnabled=false;ctx.drawImage(f.image,-r-12,-r-12,(r+12)*2,(r+12)*2);paintedFXDraws++;ctx.restore();}
function preMotionDrawFormEffects(){const t=p.attack>0?1-p.attack/(p.swingLength||.3):0,tier=maskTier();if(p.attack>0){if(['aren','blade','nox','mirror','reaper'].includes(run.mask))drawBladeTrail(run.mask,t,tier);else if(run.mask==='frost'&&t>.2&&t<.8){const f=naturalBasicFrame('frost'),w=100+p.attackCharge*60;naturalSprite(f,p.x+15+p.dir*(40+w*.25),p.y+22,w,p.swingDir,0,.8,1);}else if(['beast','puppet','tide'].includes(run.mask)&&t>.2&&t<.8)naturalSprite(naturalBasicFrame(run.mask),p.x+15+p.dir*(40+t*25),p.y+24,run.mask==='puppet'?130:70+(tier-1)*18,p.swingDir,Math.sin(t*Math.PI)*.12,.8,run.mask==='puppet'?.65:1);}if(p.chargeHeld>0&&tier>1)naturalSprite(naturalBasicFrame(run.mask),p.x+15+p.dir*24,p.y+5,28+Math.min(.9,p.chargeHeld)*30,p.dir,0,.3);if(p.parry>0)paintFX('parry',p.x+15+p.dir*32,p.y+17,55,.16,p.dir,0,.85);}
function preMotionDrawFormShot(s){if(!s.friendly)return preJourneyDrawFormShot(s);const tier=s.tier||1,id=s.owner||run.mask,role=s.role||(s.basic?'basic':s.gear?'item':'skill1'),angle=Math.atan2(s.vy,s.vx);if(role==='basic'){const size=s.owner==='frost'?50:s.owner==='storm'?37:s.owner==='engineer'?27:clamp(Math.max(s.w,s.h)*1.7,22,47);if(naturalSprite(naturalBasicFrame(id),s.x,s.y,size*(1+(tier-1)*.12),1,angle,.95))return;}else if(role==='item'){if(paintFX('item',s.x,s.y,30,.2,1,angle,.8))return;}else if(s.batch&&effects.some(a=>a.kind==='skillMotion'&&a.batch===s.batch)){naturalSprite(naturalBasicFrame(id),s.x,s.y,s.phoenix?46:25,1,angle,.65);return;}else if(naturalSprite(naturalSkillFrame(id,role),s.x,s.y,s.phoenix?130:s.wave?90:clamp(Math.max(s.w,s.h)*2,35,95),1,angle,.85))return;preJourneyDrawFormShot(s);}
function preRecastDrawPaintedFX(a){if(a.kind==='skillMotion'){drawSkillVisual(a);return true;}if(a.batch&&effects.some(b=>b.kind==='skillMotion'&&b.batch===a.batch)&&a.role!=='basic'&&a.role!=='hit')return true;if(a.kind==='lootReveal'){drawLootAura(a.rarity||0,a.x,a.y,1-a.life/a.max,1);return true;}if(a.kind==='formAttack')return true;const t=1-a.life/a.max;if(a.kind==='impact'||a.kind==='remnant'||a.kind==='cut'){const size=a.itemFX?42:Math.min(29,Math.max(15,(a.r||50)*.3));return paintFX(a.itemFX?'item':'parry',a.x,a.y,size,.05+t*.8,a.dir||1,a.angle||0,Math.min(1,a.life*9));}if(a.kind==='pickup')return paintFX('pickup',a.x,a.y,36,t,1,0,1);if(a.kind==='enemySlash')return naturalSprite(naturalBasicFrame('aren'),a.x+a.dir*20,a.y,Math.min(145,a.r*1.1),a.dir,.1,.85);if(a.kind==='dashWake')return true;if(a.kind==='groundWave')return naturalSprite(naturalBasicFrame('warden'),a.x,a.y-8,50,1,0,1-t,.6);if(['painted','slash','ring','nova'].includes(a.kind)){const role=a.role||'hit';if(role==='basic'||role==='hit')return paintFX('parry',a.x,a.y,24,.1+t*.8,a.dir||1,0,.8);if(role==='item')return paintFX('item',a.x,a.y,55,t,a.dir||1,0,.9);return naturalSkill(a.family||run.mask,role,a.x,a.y,a.r||90,t,a.dir||1,a.tier||1);}return false;}
function drawPaintedZone(z){if(z.batch&&effects.some(a=>a.kind==='skillMotion'&&a.batch===z.batch))return true;if(!['gravity','scythe','ice','frostfield','bladecut','shade','firetrail','meteor','quake','execute','volatile','echo'].includes(z.kind))return false;const siblings=z.batch?zones.filter(a=>a.batch===z.batch&&a.kind===z.kind&&a.owner===z.owner):[z];if(siblings[0]!==z)return true;const left=Math.min(...siblings.map(a=>a.x-a.r)),right=Math.max(...siblings.map(a=>a.x+a.r)),x=(left+right)/2,role=z.role||'skill1',id=z.owner||run.mask,active=siblings.filter(a=>a.delay<=0),t=active.length?['gravity','scythe','frostfield','shade','firetrail'].includes(z.kind)?.25+Math.sin(visualTime*2)*.06:clamp(1-Math.min(...active.map(a=>a.life))/.35,0,.92):.05;return naturalSkill(id,role,x,z.y-30,Math.min(360,(right-left)/2),t,1,z.tier||1,active.length?.78:.18);}
function drawPaintedLegacyFX(a){if(a.batch&&effects.some(b=>b.kind==='skillMotion'&&b.batch===a.batch))return true;if(a.kind==='warning')return true;const t=1-a.life/a.max,role=a.role||'basic',s=p.legacy,group=a.batch&&s?s.fx.filter(b=>b.batch===a.batch&&b.kind===a.kind):[a];if(group[0]!==a)return true;if(a.kind==='summon')return paintFX('item',a.x,a.y,48,t,1,0,.65);if(role==='basic'){if(a.kind==='heavy')return naturalSprite(naturalBasicFrame('warden'),a.x,a.y-14,[85,135,190][(a.tier||1)-1],a.dir||1,0,1-t);if(['slash','claw'].includes(a.kind))return true;return naturalSprite(naturalBasicFrame(a.owner||run.mask),a.x,a.y,Math.min(85,a.r),a.dir||1,0,(1-t)*.7);}const left=Math.min(...group.map(b=>b.x-b.r)),right=Math.max(...group.map(b=>b.x+b.r));return naturalSkill(a.owner||run.mask,role,(left+right)/2,a.y-(a.kind==='geyser'?30:0),Math.min(350,(right-left)/2),t,a.dir||1,a.tier||1);}
function drawLootAura(r,x,y,progress=1,alpha=.6){r=clamp(r,0,2);const index=progress>=.98?2:Math.min(3,Math.floor(progress*4)),f=atlasCell(naturalImages.reveal,r*4+index,4,3,'loot-reveal:'+r+':'+index);if(f)naturalSprite(f,x,y,[64,126,188][r],1,0,alpha);}

const DAMAGE_TYPES={physical:{name:'물리',short:'물',color:'#f0c389'},magical:{name:'마법',short:'마',color:'#afaaff'}};
const MASK_DAMAGE={aren:['physical','physical','physical','physical'],blade:['physical','physical','physical','physical'],ember:['magical','magical','magical','magical'],frost:['physical','magical','magical','magical'],storm:['physical','physical','magical','magical'],reaper:['physical','physical','magical','magical'],warden:['physical','physical','physical','physical'],nox:['physical','physical','magical','magical'],beast:['physical','physical','magical','physical'],rider:['physical','physical','physical','physical'],necro:['magical','physical','magical','magical'],chrono:['physical','magical','magical','magical'],puppet:['physical','physical','physical','physical'],engineer:['physical','physical','magical','physical'],tide:['magical','magical','magical','magical'],mirror:['physical','physical','physical','magical']};
const ITEM_COMBAT={
 roadblade:['physical'],windblade:['physical','physical'],coalstaff:['magical','magical'],icepike:['physical'],stormstring:['physical','magical'],moonedge:['physical'],stonehammer:['physical'],gardenfang:['physical','physical'],glassreaper:['physical','magical'],heartforge:['magical','magical'],heartplate:['universal','physical'],echojewel:['universal','magical'],
 dawnSword:['physical'],blackMoon:['physical'],frostRapier:['physical'],abandonedGuard:['physical'],tempestLance:['physical'],riftFang:['physical','physical'],thornArmor:['universal','physical'],emberBand:['magical','magical'],manaCycle:['magical'],stormRing:['universal','magical'],counterSeal:['universal','physical'],eternalDawn:['physical']
};
const ALLY_DAMAGE={wolf:'physical',owl:'magical',wisp:'magical',bone:'physical',revenant:'physical',revenantBow:'physical',turret:'physical',drone:'physical',puppet:'physical',dragon:'magical',mirror:'physical',deathKnight:'physical'};
let attackContext=null;
function validDamageType(t){return Object.hasOwn(DAMAGE_TYPES,t);}
function maskDamageType(id=run.mask,role='basic'){const i=role==='ultimate'?3:role==='skill2'?2:role==='skill1'?1:0;return MASK_DAMAGE[id]?.[i]||'physical';}
function maskDamageProfile(id=run.mask){const a=MASK_DAMAGE[id]||MASK_DAMAGE.aren;return a.every(t=>t==='physical')?'물리형':a.every(t=>t==='magical')?'마법형':'혼합형';}
function damageTypeName(type){return DAMAGE_TYPES[type]?.name||(type==='mixed'?'혼합':'공용');}
function currentDamageType(){return validDamageType(attackContext?.type)?attackContext.type:maskDamageType();}
function withDamageContext(type,owner,role,fn,args=[],side='player'){const before=attackContext;attackContext={type:validDamageType(type)?type:'physical',owner,role,side};try{return fn(...args);}finally{attackContext=before;}}
function damageFromElement(element){return ['fire','ice','freeze','shadow','lightning','poison','light','arcane'].includes(element)?'magical':'physical';}
function zoneDamageType(kind){return ['meteor','ice','frostfield','shade','gravity','scythe','execute','volatile','echo','poison','firetrail'].includes(kind)?'magical':'physical';}
function damageTypeTag(type,label='피해'){return `<span class="damage-tag damage-${type}">${damageTypeName(type)} ${label}</span>`;}
function maskTypeSummary(id){return maskDamageProfile(id)+' · Z '+damageTypeName(maskDamageType(id))+' / A '+damageTypeName(maskDamageType(id,'skill1'))+' / S '+damageTypeName(maskDamageType(id,'skill2'))+' / D '+damageTypeName(maskDamageType(id,'ultimate'));}
function initializeItemCombat(){for(const[id,h]of Object.entries(ITEMS)){const a=ITEM_COMBAT[id]||['universal'];h.affinity=a[0];h.procDamageType=a[1]||null;h.physicalPower=h.affinity==='magical'?0:h.power||0;h.magicalPower=h.affinity==='physical'?0:h.power||0;h.combatLabel=h.affinity==='universal'?'공용 · 물리/마법 빌드':damageTypeName(h.affinity)+' 공격용';h.originalDesc=h.desc;h.desc=h.desc.replace(/기본 위력|위력/g,h.affinity==='universal'?'공용 위력':damageTypeName(h.affinity)+' 위력');if(id==='roadblade')h.desc='물리 위력 +3. 물리 공격에 깃드는 단순한 칼날.';h.desc='['+h.combatLabel+'] '+h.desc+(h.procDamageType?' 추가 공격: '+damageTypeName(h.procDamageType)+' 피해.':'');}TRAINING.blade.desc='물리 공격의 기본 위력 +3. 마법 공격에는 적용되지 않습니다. 최대 3단계.';TRAINING.arcana.desc='마법 피해 +5%. 마법 기본 공격·스킬·소환·지속 피해에 적용. 물리 기술에는 적용되지 않습니다.';}
function itemAffinityMatches(id,type=currentDamageType()){return !ITEMS[id]||ITEMS[id].affinity==='universal'||ITEMS[id].affinity===type;}
function itemProcCompatible(proc,type){return Object.entries(ITEMS).some(([id,h])=>h.proc===proc&&run.inventory.some(a=>a.id===id&&Object.values(run.equipment).includes(a.uid))&&itemAffinityMatches(id,type));}
function itemProcDamageType(proc){return Object.entries(ITEMS).find(([id,h])=>h.proc===proc&&run.inventory.some(a=>a.id===id&&Object.values(run.equipment).includes(a.uid)))?.[1].procDamageType||currentDamageType();}
function itemForEffect(effect){return Object.entries(ITEMS).find(([id,h])=>h.effect===effect&&run.inventory.some(a=>a.id===id&&Object.values(run.equipment).includes(a.uid)));}
function runGearEffect(effect,event,ctx,fn){const item=itemForEffect(effect),id=item?.[0],h=item?.[1];if(['hit','beforeHit'].includes(event)&&ctx.damageType&&h&&!itemAffinityMatches(id,ctx.damageType))return;if(h?.procDamageType&&['hit','hurt'].includes(event))return withDamageContext(h.procDamageType,id,'item',fn,[ctx]);return fn(ctx);}
function gearStats(r=run){const s=preTypeGearStats(r),type=attackContext?.side==='player'?currentDamageType():maskDamageType(r.mask);s.physicalPower=0;s.magicalPower=0;s.crit=0;s.haste=0;for(const uid of Object.values(r?.equipment||{})){const a=r.inventory?.find(a=>a.uid===uid),h=a&&ITEMS[a.id];if(!h)continue;s.physicalPower+=h.physicalPower||0;s.magicalPower+=h.magicalPower||0;if(h.affinity==='universal'||h.affinity===type){s.crit+=h.crit||0;s.haste+=h.haste||0;}}s.haste=clamp(s.haste,-.25,.25);s.crit=Math.max(0,s.crit);s.power=type==='magical'?s.magicalPower:s.physicalPower;return s;}
function damage(r=run,type=attackContext?.side==='player'?currentDamageType():maskDamageType(r.mask)){return 22+(type==='physical'?Math.min(3,r.up?.blade||0)*3:0)+(type==='magical'?gearStats(r).magicalPower:gearStats(r).physicalPower);}
function sagaStats(r=run){const s=preTypeSagaStats(r);s.physicalPower=damage(r,'physical');s.magicalPower=Math.round(damage(r,'magical')*(1+(r.training?.arcana||0)*.05)*10)/10;s.damageProfile=maskDamageProfile(r.mask);return s;}
function preIdentityStartAttack(charge=0){p.attackDamageType=maskDamageType();p.attackOwner=run.mask;return withDamageContext(p.attackDamageType,run.mask,'basic',preTypeStartAttack,[charge]);}
function resolveBasic(dt){return withDamageContext(p.attackDamageType||maskDamageType(),p.attackOwner||run.mask,'basic',preTypeResolveBasic,[dt]);}
function preRecastCastSkill(slot,swap=false){if(p['skill'+slot+'CD']>0&&!swap)return;const type=maskDamageType(run.mask,'skill'+slot),result=withDamageContext(type,run.mask,'skill'+slot,preTypeCastSkill,[slot,swap]);if(p.rushTime>0)p.rushDamageType=type;if(p.slam)p.slamDamageType=type;return result;}
function preRecastCastUltimate(){return withDamageContext(maskDamageType(run.mask,'ultimate'),run.mask,'ultimate',preTypeCastUltimate);}
function castMagic(){return withDamageContext('magical',run.mask,'magic',preTypeCastMagic);}
function parrySuccess(x){return withDamageContext(run.mask==='frost'?'magical':'physical',run.mask,'parry',preTypeParrySuccess,[x]);}
function preRecastHitEnemy(e,amount,dir=1,parried=false,kind='sword',explicitType=null){if(e.dead||amount<=0)return;const type=validDamageType(explicitType)?explicitType:kind==='dot'?'magical':attackContext?.side==='player'?currentDamageType():kind==='fall'||kind==='self'?'physical':kind==='magic'?'magical':maskDamageType(run.mask,fxRole||(['sword','finisher','parry'].includes(kind)?'basic':'skill1')),owner=attackContext?.side==='player'?attackContext.owner:run.mask,before=e.hp;const result=withDamageContext(type,owner,kind,preTypeHitEnemy,[e,amount,dir,parried,kind]);e.lastDamage={type,owner,kind,amount:Math.max(0,before-e.hp)};return result;}
function projectile(options={}){const type=validDamageType(options.damageType)?options.damageType:attackContext?.side==='player'?currentDamageType():options.gear?damageFromElement(options.element):maskDamageType(options.owner||run.mask,options.role||fxRole||(options.basic?'basic':'skill1')),owner=options.owner||(Object.hasOwn(FORMS,attackContext?.owner)?attackContext.owner:run.mask);return withDamageContext(type,owner,options.role||fxRole||'basic',preSagaProjectile,[{...options,damageType:type,owner}]);}
function addZone(kind,x,y,r,delay=0,extra={}){const hostile=['enemyroot','poison'].includes(kind),type=extra.damageType||(hostile?zoneDamageType(kind):attackContext?.side==='player'?currentDamageType():zoneDamageType(kind)),owner=extra.owner||attackContext?.owner||run.mask;return withDamageContext(type,owner,extra.role||fxRole||'skill1',preSagaAddZone,[kind,x,y,r,delay,{...extra,damageType:type,owner,hostile}],hostile?'enemy':'player');}
function areaHit(x,y,r,dmg,element='wind',kind='skill',explicitType=null){const type=validDamageType(explicitType)?explicitType:attackContext?.side==='player'?currentDamageType():damageFromElement(element);return withDamageContext(type,attackContext?.owner||run.mask,attackContext?.role||kind,preSagaAreaHit,[x,y,r,dmg,element,kind]);}
function applyStatus(e,element,seconds=2){const result=preSagaApplyStatus(e,element,seconds);if(element==='fire'){e.burnDamageType='magical';e.burnOwner=attackContext?.owner||run.mask;e.burnDamage=damage(run,'magical')*.14;}return result;}
function preRecastShotStep(s,dt){const type=s.damageType||(s.friendly?maskDamageType(s.owner||run.mask,s.role||'basic'):s.enemyDamageType||'physical');s.damageType=type;return withDamageContext(type,s.owner||s.enemyOwner||'projectile',s.role||'projectile',preSagaShotStep,[s,dt],s.friendly?'player':'enemy');}
function preRosterEnemyDamageType(e,projectile=false){if(['wisp','shaman','echo'].includes(e.type)||e.archetype==='shadeweaver')return'magical';if(e.type==='boss'&&projectile)return'magical';if(e.type==='boss'&&['weaver','memory','seradion','elion','uncrowned'].includes(e.spec?.kind))return'magical';return'physical';}
function incomingDamageType(kind){if(/추락|가시|검격|참격|베기|검무|강타|돌진|충돌|창/.test(kind))return'physical';if(/포자|화염|화상|마법|맥동|광선|냉기|그림자|달빛|태양|영혼|분출|반동|마력|분광|공명/.test(kind))return'magical';return attackContext?.side==='enemy'?currentDamageType():'physical';}
function preRecastHurt(amount,sourceX,kind='적의 공격',explicitType=null){const type=explicitType||incomingDamageType(kind),before=p.hp,result=withDamageContext(type,attackContext?.owner||'environment',kind,preTypeHurt,[amount,sourceX,kind],'enemy');if(p.hp<before)p.lastIncoming={type,amount:before-p.hp,kind};return result;}
function preRecastEnemyStep(e,dt){return withDamageContext(enemyDamageType(e),e.type,e.spec?.kind||e.type,preTypeEnemyStep,[e,dt],'enemy');}
function hostileShot(x,y,vx,vy,extra={}){const e=level.boss,type=extra.damageType||'magical';return preSagaHostileShot(x,y,vx,vy,{...extra,damageType:type,enemyOwner:attackContext?.owner||e?.spec?.kind||'enemy'});}
function fireAtPlayer(e,count=1,speed=270,spread=.18){const start=shots.length,result=preSagaFireAtPlayer(e,count,speed,spread);for(const s of shots.slice(start)){s.damageType=enemyDamageType(e,true);s.enemyOwner=e.type;}return result;}
function formSystem(dt){if(level?.puzzle)return;return withDamageContext(p.slam?p.slamDamageType||'physical':p.rushTime>0?p.rushDamageType||maskDamageType(run.mask,'skill1'):maskDamageType(),run.mask,'motion',preTypeFormSystem,[dt]);}
function procRelics(e,kind,heavy,dir){return withDamageContext('magical','inscription','item',preSagaProcRelics,[e,kind,heavy,dir]);}
function chainGear(e,dir,m){return withDamageContext('magical','stormstring','item',preSagaChainGear,[e,dir,m]);}
function damageNumber(amount,type=currentDamageType()){return DAMAGE_TYPES[type].short+' '+Math.round(amount);}
function itemCombatDescription(id){const h=ITEMS[id],types=MASK_DAMAGE[run.mask],match=h.affinity==='universal'?'모든 가면에 적용':types.every(t=>t===h.affinity)?'현재 가면의 모든 공격과 맞음':types.includes(h.affinity)?'현재 가면의 '+damageTypeName(h.affinity)+' 기술에 적용':'현재 가면의 공격 위력에는 적용되지 않음';return `<div class="item-combat-info">${damageTypeTag(h.affinity,h.affinity==='universal'?'장비':'공격용')}<p>${match}</p>${h.procDamageType?'<p>발동 추가 공격 · '+damageTypeName(h.procDamageType)+' 피해</p>':''}${h.power?'<p>물리 위력 +'+h.physicalPower+' · 마법 위력 +'+h.magicalPower+'</p>':''}</div>`;}
function renderSatchel(){preTypeRenderSatchel();const a=run.inventory.find(a=>a.uid===selectedBagUID);if(a){const detail=document.querySelector('.satchel-detail');detail.querySelector('h3').insertAdjacentHTML('afterend',itemCombatDescription(a.id));}const h=document.querySelector('.satchel-top h2');h.insertAdjacentHTML('beforeend',`<span class="bag-form-type">${FORMS[run.mask].name} · ${maskDamageProfile()}</span>`);}
function maskDescription(){const id=run.mask,h=FORMS[id];let html=preTypeMaskDescription();for(const[key,role,label]of [['Z','basic','기본 공격'],['A','skill1',h.s1],['S','skill2',h.s2],['D','ultimate',h.ultimate||'스킬 3']])html=html.replace('<b>'+key+' · '+label+'</b>','<b>'+key+' · '+label+'</b>'+damageTypeTag(maskDamageType(id,role)));return html.replace('<div class="skill-notes">','<div class="mask-damage-summary">'+maskTypeSummary(id)+(id==='beast'?' · 늑대: 물리 / 정령·부엉이: 마법':id==='necro'?' · 부활체는 원래 공격 속성 유지 / 망령 기사: 물리':id==='engineer'?' · 포탑·드론: 물리 / 자력 기술: 마법':'')+'</div><div class="skill-notes">');}
function preFinalProductInfo(a){const h=preTypeProductInfo(a);if(a.offer.kind==='item'){h.kind=ITEMS[a.offer.id].combatLabel+' · 장비';}if(a.offer.kind==='mask'){h.kind=maskDamageProfile(a.offer.id)+' · 변신 가면';h.desc=maskTypeSummary(a.offer.id)+' · '+h.desc;}if(a.offer.kind==='food')h.kind='공용 · 회복/성장';return h;}
function preRecastUpdateCombatUI(){preTypeUpdateCombatUI();$('player-title').textContent+=' · '+maskDamageProfile();for(const[id,role]of [['attack-status','basic'],['skill1-status','skill1'],['skill2-status','skill2'],['ult-status','ultimate']]){const parent=$(id).parentElement,type=maskDamageType(run.mask,role);let chip=parent.querySelector('.damage-type-chip');if(!chip){chip=document.createElement('span');parent.append(chip);}chip.className='damage-type-chip damage-'+type;chip.textContent=damageTypeName(type);parent.dataset.tip=(parent.dataset.tip||'').replace(/ · \[(물리|마법) 피해\]$/,'')+' · ['+damageTypeName(type)+' 피해]';}}
initializeItemCombat();for(const[id,h]of Object.entries(RELICS)){h.affinity='universal';h.procDamageType=['conductor','shatter','volatile','mirror','echo'].includes(id)?'magical':null;h.desc='[공용 각인] '+h.desc+(h.procDamageType?' 추가 공격: 마법 피해.':'');}

function marketRerollCost(l=level){return Math.min(220,40+Math.floor(l.stage/20)*20+(l.rerollCount||0)*20);}
function configureShop(l){const rerolls=run.marketStock?.[l.stage]?.rerollCount||0;preFinalConfigureShop(l);l.rerollCount=rerolls;l.stock.rerollCount=rerolls;configureMarket(l);}
function configureMarket(l){const order=['weapon','armor','ring','aux','mask','food','evolution'];l.products=[{category:'reroll',index:0,offer:{kind:'reroll',id:'reroll',price:marketRerollCost(l)},x:155,y:FLOOR-75,token:'market:reroll'}];l.marketGroups=[];l.shops=[];let cursor=350;for(const category of order){const start=cursor,offers=category==='evolution'?[{kind:'evolution',id:'evolution',price:0}]:l.stock[category]||[];for(let index=0;index<offers.length;index++){const offer=offers[index];l.products.push({category,index,offer,x:start+325+index*174,y:FLOOR-80,token:'market:'+category+':'+index});}const group={category,start,end:start+820,center:start+490,vendorX:start+115};l.marketGroups.push(group);l.shops.push({category,x:group.vendorX,y:FLOOR});cursor+=900;}l.width=cursor+280;l.portal.x=l.width-145;l.memory.x=l.width-280;l.sectors[0].end=l.width;l.plats[0].w=l.width;l.routeGroups[0].end=l.width;l.props=[];l.signs=[];if(l.checkpoint)l.checkpoint.x=l.portal.x+29;positionMarketNPCs(l);}
function positionMarketNPCs(l){if(!l.shop)return;l.npcs=(l.npcs||[]).filter(n=>!n.marketVendor&&!n.id.startsWith('merchantTalk'));for(const n of l.npcs)if(n.gift)n.x=l.width-390;for(const g of l.marketGroups){l.npcs.push({id:'marketOwner:'+g.category,marketVendor:true,speaker:MARKET_NAMES[g.category],text:g.category==='evolution'?'금화가 아니라 분해 보석을 가져와. 같은 가면도 세 번째 단계에서는 다른 유산을 남기지.':'이 지하 길은 안전해. 상품 앞에서 V로 사고, 가면은 V를 두 초 동안 눌러 확인해. R로 진열을 바꾸려면 '+marketRerollCost(l)+' G가 필요해.',x:g.vendorX,y:FLOOR,sector:0});}}
function rerollMarket(){if(mode!=='playing'||!level.shop)return false;const cost=marketRerollCost();if(run.coins<cost){toast('리롤에 '+cost+' G 필요 · 현재 '+run.coins+' G');return false;}const before=level.stock,roll=(level.rerollCount||0)+1,r=makeRng(level.seed+roll*87137+9467),quality=run.stage<21?1:run.stage<61?2:3,stock={rerollCount:roll};for(const cat of['weapon','armor','ring','aux']){let pool=Object.keys(ITEMS).filter(id=>ITEMS[id].slot===cat&&!ITEMS[id].bound&&ITEMS[id].rarity<=quality);const fresh=pool.filter(id=>!(before[cat]||[]).some(a=>a.id===id));if(fresh.length>=2)pool=fresh;stock[cat]=shuffleWith(r,pool).slice(0,2).map(id=>({kind:'item',id,price:ITEMS[id].price,sold:false}));}let masks=availableForms().filter(id=>!run.artifacts.includes(id)&&maskRarity(id)<=(run.stage<21?1:2));const count=run.stage<21?1:2,fresh=masks.filter(id=>!before.mask.some(a=>a.id===id));if(fresh.length>=count)masks=fresh;stock.mask=shuffleWith(r,masks).slice(0,count).map(id=>({kind:'mask',id,price:380+maskRarity(id)*260+Math.floor(run.stage/10)*70,sold:false}));stock.food=['soup','meal','elixir'].map((id,i)=>({kind:'food',id,price:[90,160,120][i],sold:false}));run.coins-=cost;level.rerollCount=roll;level.stock=stock;run.marketStock[run.stage]=stock;configureMarket(level);p.pickupHold=null;p.holdLatch=held.has('interact');level.focusProduct=null;acquireFX(1,p.x+15,FLOOR-90);audio.sfx('coin');toast('상품을 새로 진열했습니다 · 다음 리롤 '+marketRerollCost()+' G');updateHUD();return true;}
function productInfo(a){if(a.offer.kind==='reroll')return{name:'지하 상단의 진열 교체',key:'utility:coins',rarity:1,kind:'R / V · 유료 리롤',desc:'모든 매대의 상품을 다시 고릅니다. 구입한 물건은 보존됩니다. 가면은 초반 1개·후반 최대 2개이며 리롤할수록 비용이 늘어납니다.',price:marketRerollCost(),sold:false};return preFinalProductInfo(a);}
function purchaseOffer(product,fromCatalogue=false){if(product?.offer.kind==='reroll')return rerollMarket();return preFinalPurchaseOffer(product,fromCatalogue);}
function drawBackground(theme,cam=0,chapter=0,menuView=false){if(!level?.shop||menuView){ctx.save();ctx.filter=worldStop&&mode==='playing'?'grayscale(1) contrast(.78) brightness(.64)':'saturate(.62) contrast(.78) brightness(.74)';const result=preSagaDrawBackground(theme,cam,chapter,menuView);ctx.restore();return result;}ctx.fillStyle='#0b121d';ctx.fillRect(0,0,W,H);if(undergroundImage.complete&&undergroundImage.naturalWidth){const h=FLOOR/.618,w=h*undergroundImage.naturalWidth/undergroundImage.naturalHeight;for(let x=-((cam*.94)%w)-w;x<W+w;x+=w)ctx.drawImage(undergroundImage,x,0,w,h);}const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#070b14aa');g.addColorStop(.4,'#14213100');g.addColorStop(1,'#0b111c33');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);}
function prePaintedDrawPlatform(f){if(level?.shop&&f.kind==='ground')return;return preSagaDrawPlatform(f);}
function drawMarketScenery(){if(!level.shop)return;ctx.save();for(const g of level.marketGroups){if(g.end<camera.x-120||g.start>camera.x+W+120)continue;const index=g.category==='food'?1:g.category==='ring'?3:['mask','aux','evolution'].includes(g.category)?2:0;drawMarketVendor(index,g.vendorX,FLOOR);drawPedestal(g.vendorX,false,126);ctx.textAlign='center';ctx.font='700 19px WildrootUI, WildrootUI';rr(g.center-150,FLOOR-311,300,43,2,'#31261fea','#ad8b54');ctx.fillStyle='#f2dfb6';ctx.fillText(MARKET_NAMES[g.category],g.center,FLOOR-283);ctx.font='500 13px WildrootUI, WildrootUI';ctx.fillStyle='#e2c991';ctx.fillText(g.category==='evolution'?'분해 보석으로 3단계 진화':g.category==='mask'?'물리형 · 마법형 · 혼합형':'상품 앞에서 V로 확인·구매',g.center,FLOOR-260);if(level.focusNPC?.id==='marketOwner:'+g.category&&!level.focusProduct){ctx.fillStyle='#f7e9ba';ctx.fillText('V · 상인과 대화',g.vendorX,FLOOR-195);}}ctx.textAlign='center';ctx.font='700 17px WildrootUI, WildrootUI';ctx.fillStyle='#f1d08b';ctx.fillText('R · 상품 리롤 '+marketRerollCost()+' G',155,FLOOR-195);ctx.font='500 13px WildrootUI, WildrootUI';ctx.fillStyle='#e4d6b1';ctx.fillText('지하 상단 · 전투 없음',155,FLOOR-220);ctx.restore();}
function readableLines(text,width,font='500 14px WildrootUI, WildrootUI'){ctx.font=font;const lines=[];for(const paragraph of String(text).split('\n')){let line='';for(const char of paragraph){if(ctx.measureText(line+char).width>width&&line){lines.push(line);line=char;}else line+=char;}lines.push(line);}return lines;}
function drawModelTooltip(info,x,y,action,hold=null){const w=400,desc=readableLines(info.desc||'',w-36),actions=readableLines(action,w-36,'700 14px WildrootUI, WildrootUI'),h=Math.min(395,104+desc.length*22+actions.length*22+36);x=clamp(x-w/2,camera.x+16,camera.x+W-w-16);y=clamp(y-camera.y,100,FLOOR-h-90)+camera.y;ctx.save();rr(x,y,w,h,3,'#eee1c5fa','#6c5735');pixelRect(x+1,y+1,w-2,5,RARITY[info.rarity??1][1]);drawItemModel(info.key,x+39,y+42,52);ctx.textAlign='left';ctx.font='700 18px WildrootUI, WildrootUI';ctx.fillStyle='#2c281f';ctx.fillText(info.name,x+75,y+31);ctx.font='600 12px WildrootUI, WildrootUI';ctx.fillStyle='#65553c';ctx.fillText((info.kind||'유물')+' · '+RARITY[info.rarity??1][0],x+75,y+54);ctx.font='500 14px WildrootUI, WildrootUI';ctx.fillStyle='#3b3428';desc.slice(0,9).forEach((line,i)=>ctx.fillText(line,x+18,y+88+i*22));ctx.font='700 14px WildrootUI, WildrootUI';ctx.fillStyle='#28482f';actions.slice(0,2).forEach((line,i)=>ctx.fillText(line,x+18,y+h-45-(actions.length-1-i)*22));if(hold){pixelRect(x+18,y+h-25,w-36,9,'#b6aa89');pixelRect(x+18,y+h-25,(w-36)*hold.progress/2,9,'#477950');}else{ctx.font='500 12px WildrootUI, WildrootUI';ctx.fillStyle='#63523b';ctx.fillText(/변신|가면/.test(info.kind)?'1 / 2 · 교체 칸 선택':'B · 가방에서 자세히 보기',x+18,y+h-18);}ctx.restore();}
window.addEventListener('keydown',e=>{if(!e.repeat&&!e.defaultPrevented&&e.code==='KeyR'&&!bindings.KeyR&&mode==='playing'&&level.shop){e.preventDefault();rerollMarket();}});

const SKILL_COOLDOWNS={aren:[10,15,38],blade:[10,17,44],ember:[13,19,58],frost:[12,18,48],storm:[11,17,50],reaper:[12,20,54],warden:[13,19,56],nox:[12,18,52],beast:[14,20,56],rider:[11,17,48],necro:[15,22,60],chrono:[16,24,76],puppet:[13,21,58],engineer:[14,22,62],tide:[14,21,60],mirror:[13,21,56]};
let worldStop=null,ultimateScene=null,timeRelease=0;
function skillCooldown(slot,id=run.mask){return Math.round(SKILL_COOLDOWNS[id][slot-1]*(1+(run.formEvolution?.[id]||0)*.05)*(1-gearStats().skill*(slot===3?.5:1))*(run.placeTuning===journeyPlace().id?.92:1)*10)/10;}
function saveSkillCooldowns(){if(!p||!run)return;run.skillCooldowns=run.skillCooldowns||{};for(const[id,a]of Object.entries(p.cooldowns||{}))if(id!==run.mask)run.skillCooldowns[id]={s1:a.s1||0,s2:a.s2||0,s3:a.s3||0};run.skillCooldowns[run.mask]={s1:p.skill1CD||0,s2:p.skill2CD||0,s3:p.skill3CD||0};}
function freshRun(){worldStop=null;ultimateScene=null;const r=preRecastFreshRun();r.skillCooldowns={};r.maskGrades={};r.placeTuning=0;return r;}
function preCoopValidateRun(r){const c=preRecastValidateRun(r);c.skillCooldowns={};for(const id of Object.keys(FORMS)){const a=r.skillCooldowns?.[id];if(a)c.skillCooldowns[id]=Object.fromEntries(['s1','s2','s3'].map(k=>[k,Number.isFinite(a[k])?clamp(a[k],0,180):0]));}c.maskGrades={};for(const id of c.artifacts)c.maskGrades[id]=clamp(Number.isInteger(r.maskGrades?.[id])?r.maskGrades[id]:MASK_RARITY[id],MASK_RARITY[id],2);c.placeTuning=Number.isInteger(r.placeTuning)?clamp(r.placeTuning,0,21):0;for(const[k,w]of Object.entries(c.worldState))w.services=Array.isArray(r.worldState?.[k]?.services)?r.worldState[k].services.filter(a=>typeof a==='string').slice(0,12):[];return c;}
function preCoopEnterStage(stage){worldStop=null;ultimateScene=null;timeRelease=0;preRecastEnterStage(stage);p.cooldowns=clone(run.skillCooldowns||{});const c=run.skillCooldowns?.[run.mask]||{};p.skill1CD=c.s1||0;p.skill2CD=c.s2||0;p.skill3CD=c.s3||0;p.energy=100;p.salvageHold=null;p.salvageLatch=false;updateHUD();}
function activateForm(id,switching=false){saveSkillCooldowns();const s3=p.skill3CD||0,old=run.mask,result=preRecastActivateForm(id,switching);p.cooldowns[old]={...(p.cooldowns[old]||{}),s3};p.skill3CD=p.cooldowns[id]?.s3??run.skillCooldowns?.[id]?.s3??0;return result;}
function preIdentityCastSkill(slot,swap=false){if(p['skill'+slot+'CD']>0&&!swap)return;const type=maskDamageType(run.mask,'skill'+slot),result=preRecastCastSkill(slot,swap);p['skill'+slot+'CD']=skillCooldown(slot);const near=liveTargets(p.x+15,600)[0];if(run.mask==='aren'&&slot===2)p.parry=Math.max(p.parry,.3);if(run.mask==='frost'&&slot===1){for(const s of shots)if(!s.friendly&&Math.abs(s.x-p.x)<175)s.life=0;}if(run.mask==='necro'&&slot===2){const s=maskState(),a=s.allies.sort((a,b)=>a.life-b.life)[0];if(a){a.life=0;const x=near?near.x+near.w/2:a.x;withDamageContext('magical','necro','skill2',()=>areaHit(x,playerCombatFloor()-40,150,damage()*1.4,'shadow','skill'));}}if(run.mask==='mirror'&&slot===2&&near)withDamageContext('physical','mirror','skill2',()=>maskEvent(.12,near.x+near.w/2,near.y+near.h/2,100,1.1,'mirror'));if(run.mask==='warden'&&slot===2)p.parry=Math.max(p.parry,.25);if(run.mask==='puppet'&&slot===2)for(const e of maskState().links)if(!e.dead&&e.type!=='boss')e.knockX=Math.sign(p.x-e.x)*190;if(run.mask==='beast'&&slot===2)grantShield(5,3);if(run.mask==='engineer'&&slot===1)for(const a of maskState().allies)if(a.kind==='turret')a.tick=0;saveSkillCooldowns();return result;}
function preIdentityCastUltimate(){if((p.skill3CD||0)>0){toast('스킬 D · '+p.skill3CD.toFixed(1)+'초 후 준비');return false;}p.energy=100;const id=run.mask;if(id==='chrono')beginWorldStop();else preRecastCastUltimate();p.energy=100;p.skill3CD=skillCooldown(3);saveSkillCooldowns();ultimateScene={id,x:p.x+15,y:p.y+24,life:id==='ember'?2.4:1.5,max:id==='ember'?2.4:1.5,seed:worldTime};audio.tone(id==='chrono'?62:43,.3,'sine',.16,26);return true;}
function beginWorldStop(){worldStop={remaining:[3.5,4.2,5][run.evolution||0],max:[3.5,4.2,5][run.evolution||0],elapsed:0,hits:[],owner:'chrono'};p.inv=Math.max(p.inv,.4);hitStop=Math.max(hitStop,.08);audio.noise(.24,900,.28,75);audio.tone(350,.42,'sine',.1,42);toast('정지된 세계 · 움직이는 것은 당신뿐입니다.');}
function releaseWorldStop(){if(!worldStop)return;const hits=worldStop.hits;worldStop=null;for(const a of hits)if(!a.e.dead)withDamageContext(a.type,a.owner,a.role,()=>hitEnemy(a.e,a.amount,a.dir,a.parried,a.kind,a.type));timeRelease=.5;if(hits.length){hitStop=Math.max(hitStop,.12);impact(Math.min(19,7+hits.length));audio.noise(.28,600,.35,45);}toast('시간 재개 · '+hits.length+'개의 타격이 이어집니다.');}
function preIdentityHitEnemy(e,amount,dir=1,parried=false,kind='sword',type=null){if(worldStop&&!e.dead&&kind!=='self'){if(worldStop.hits.length<120){worldStop.hits.push({e,amount,dir,parried,kind,type:type||currentDamageType(),owner:attackContext?.owner||run.mask,role:attackContext?.role||kind});effects.push({kind:'storedHit',x:e.x+e.w/2,y:e.y+e.h*.5,dir,life:.6,max:.6});floatText(e.x+e.w/2,e.y-20,'정지','#c3c6ff',14);}return;}const boss=e.type==='boss',pattern=boss?{state:e.state,wind:e.wind,cool:e.cool,action:e.action,attackNo:e.attackNo,comboIndex:e.comboIndex,fired:e.fired}:null;const owner=attackContext?.side==='player'?attackContext.owner:run.mask,grade=Math.max(0,maskRarity(owner)-(MASK_RARITY[owner]||0));amount*=1+grade*.04;const hp=e.hp,result=preRecastHitEnemy(e,amount,dir,parried,kind,type);if(boss&&!e.dead){e.knockX=0;e.stun=0;e.freeze=0;if(!parried&&['sword','finisher','skill','magic','proc','dot'].includes(kind))Object.assign(e,pattern);}if(e.hp<hp&&!['dot','self'].includes(kind)){effects.push({kind:'attackContact',x:e.x+e.w/2,y:e.y+e.h*.45,dir,role:attackContext?.role||kind,damageType:e.lastDamage?.type||currentDamageType(),life:.18,max:.18,r:kind==='ultimate'?80:['skill','finisher'].includes(kind)?54:32});if(['ultimate','skill'].includes(kind))hitStop=Math.max(hitStop,kind==='ultimate'?.065:.035);}return result;}
function hurt(amount,x,kind='적의 공격',type=null){const hp=p.hp,result=preRecastHurt(amount,x,kind,type);if(p.hp<hp){p.hurtImpact=.28;effects.push({kind:'playerHurtImpact',x:p.x+15,y:p.y+22,dir:Math.sign(p.x-x)||1,life:.25,max:.25});hitStop=Math.max(hitStop,.045);}return result;}
function preRosterEnemyStep(e,dt){if(worldStop)return;if(e.type==='boss'){e.knockX=0;e.stun=0;e.freeze=0;}return preRecastEnemyStep(e,dt);}
function preIdentityShotStep(s,dt){if(worldStop&&!s.friendly)return;return preRecastShotStep(s,dt);}
function preCoopPlayerStep(dt){preRecastPlayerStep(dt);if(mode!=='playing')return;const stats=gearStats(),rate=Math.min(.18,stats.energy*.025+(run.training?.spirit||0)*.025);p.skill1CD=Math.max(0,p.skill1CD-dt*rate);p.skill2CD=Math.max(0,p.skill2CD-dt*rate);p.skill3CD=Math.max(0,(p.skill3CD||0)-dt*(1+rate));p.hurtImpact=Math.max(0,(p.hurtImpact||0)-dt);if(worldStop){worldStop.remaining-=dt;worldStop.elapsed+=dt;if(worldStop.remaining<=0)releaseWorldStop();}if(ultimateScene&&(ultimateScene.life-=dt)<=0)ultimateScene=null;timeRelease=Math.max(0,timeRelease-dt);roadNPCStep();saveSkillCooldowns();}
function preCoopWorldRewardStep(dt,oldX=p.x,oldY=p.y){level.interactionFocus=selectInteractionFocus();const heldV=held.has('interact');if(held.has('salvage')){held.delete('interact');pressed.delete('interact');}preRecastWorldRewardStep(dt,oldX,oldY);if(heldV)held.add('interact');if(!held.has('salvage')){p.salvageHold=null;p.salvageLatch=false;return;}const c=level.focusReward?.kind==='artifact'?level.focusReward.value:level.focusLoot;if(!c||c.claimed||c.got||c.artifact&&!c.opened||p.salvageLatch||p.dash>0||p.attack>0||p.hurt>0){p.salvageHold=null;return;}if(p.salvageHold?.source!==c)p.salvageHold={source:c,progress:0};p.salvageHold.progress+=dt;if(p.salvageHold.progress>=2){if(c.artifact)shatterGroundMask(c);else shatterGroundItem(c);p.salvageHold=null;p.salvageLatch=true;}}
function drawMaskPickupTooltip(c,product=null){const id=c.artifact,h=FORMS[id],w=350,height=432,x=clamp(c.x+90+w>camera.x+W-20?c.x-w-65:c.x+90,camera.x+20,camera.x+W-w-20),y=136+camera.y,rarity=maskRarity(id);ctx.save();rr(x,y,w,height,3,'#eee1c4fc','#755b35');pixelRect(x+1,y+1,w-2,6,RARITY[rarity][1]);drawItemModel('mask:'+id,x+43,y+48,60);ctx.fillStyle='#30291e';ctx.textAlign='left';ctx.font='700 19px WildrootUI, WildrootUI';ctx.fillText(h.name,x+83,y+32);ctx.font='600 13px WildrootUI, WildrootUI';ctx.fillText(RARITY[rarity][0]+' · '+maskDamageProfile(id),x+83,y+57);ctx.font='500 13px WildrootUI, WildrootUI';readableLines(h.passive,w-30).slice(0,3).forEach((s,i)=>ctx.fillText(s,x+16,y+90+i*21));ctx.font='700 13px WildrootUI, WildrootUI';ctx.fillText('Z · '+damageTypeName(maskDamageType(id))+' 기본 공격',x+16,y+157);for(const[i,key,role,name]of [[0,'A','skill1',h.s1],[1,'S','skill2',h.s2],[2,'D','ultimate',h.ultimate||'스킬 3']]){const yy=y+177+i*62,f=naturalSkillFrame(id,role);rr(x+16,yy,46,46,2,'#29312d','#8c734a');if(f)ctx.drawImage(f.image,x+18,yy+4,42,38);ctx.font='700 14px WildrootUI, WildrootUI';ctx.fillStyle='#3c3020';ctx.fillText(key+' · '+name,x+73,yy+17);ctx.font='500 13px WildrootUI, WildrootUI';ctx.fillStyle=maskDamageType(id,role)==='magical'?'#57518c':'#80562e';ctx.fillText(damageTypeName(maskDamageType(id,role))+' · 쿨타임 '+SKILL_COOLDOWNS[id][i]+'초',x+73,yy+39);}const source=product||c,hold=p.salvageHold?.source===source?p.salvageHold:p.pickupHold?.source===source?p.pickupHold:null;ctx.font='700 13px WildrootUI, WildrootUI';ctx.fillStyle=p.salvageHold?'#843d38':'#2b513b';ctx.fillText(product?product.offer.price+' G · V 2초 구매 · 1/2 교체 칸':c.opened?'V 2초 획득 / G 2초 분해 · ◆ '+gemValue(id,true):'Z 공격 / V · 상자 열기',x+16,y+height-33);if(hold){pixelRect(x+16,y+height-20,w-32,8,'#b7a98a');pixelRect(x+16,y+height-20,(w-32)*Math.min(1,hold.progress/2),8,p.salvageHold?'#955047':'#47765e');}ctx.restore();}
