function preCoopUpdateCombatUI(){preRecastUpdateCombatUI();for(const[id,slot]of [['skill1-status',1],['skill2-status',2],['ult-status',3]]){const a=$(id).parentElement,role=slot===3?'ultimate':'skill'+slot,f=naturalSkillFrame(run.mask,role),cd=p['skill'+slot+'CD']||0;let img=a.querySelector('.skill-art');if(!img){img=document.createElement('img');img.className='skill-art';img.alt=FORMS[run.mask][slot===1?'s1':slot===2?'s2':'ultimate']||'스킬';a.append(img);}img.alt=FORMS[run.mask][slot===1?'s1':slot===2?'s2':'ultimate']||'스킬';if(f&&img.src!==f.url)img.src=f.url;$(id).textContent=cd>0?Math.ceil(cd):'';a.querySelector('.cooldown-shade').style.height=clamp(cd/skillCooldown(slot)*100,0,100)+'%';a.dataset.tip=(img.alt||'스킬')+' · '+damageTypeName(maskDamageType(run.mask,role))+' · '+skillCooldown(slot)+'초 · 에너지 소모 없음';a.classList.toggle('skill-ready',cd<=0);if(slot===3)a.classList.toggle('ultimate-ready',cd<=0);}$('energy-value').parentElement.style.display='none';$('energy-bar').parentElement.style.display='none';const f=itemModel('mask:'+run.mask);if(f)$('player-portrait').src=f.url;$('hp-value').textContent=Math.max(0,Math.ceil(p.hp))+' / '+maxHP();$('player-title').textContent=evolutionName()+' · '+maskDamageProfile();}
