function preVividDrawPaintedFX(a){if(a.kind==='skillMotion'&&a.family==='chrono'&&a.role==='ultimate'&&worldStop)return true;if(['attackContact','playerHurtImpact','storedHit'].includes(a.kind)){const t=1-a.life/a.max,size=a.kind==='playerHurtImpact'?95:a.kind==='storedHit'?38:a.r;paintFX(a.kind==='storedHit'?'item':'parry',a.x,a.y,size,t,a.dir||1,a.kind==='playerHurtImpact'?.5:-.6,1-t*.5);return true;}return preRecastDrawPaintedFX(a);}
