function drawRecastScreen(){ctx.save();if(ultimateScene&&ultimateScene.id!=='chrono'){const a=ultimateScene,t=1-a.life/a.max,alpha=Math.sin(Math.min(1,t*2)*Math.PI)*.14;ctx.fillStyle=a.id==='ember'?'#24121a':a.id==='tide'?'#0a3242':'#121323';ctx.globalAlpha=Math.max(0,alpha);ctx.fillRect(0,0,W,H);ctx.globalAlpha=1;if(a.id==='tide'){const yy=H-t*H*.33;ctx.fillStyle='#78baca28';ctx.fillRect(0,yy,W,H-yy);}if(t<.38){ctx.fillStyle='#070b14cc';ctx.fillRect(0,0,W,26*(1-t/.38));ctx.fillRect(0,H-26*(1-t/.38),W,26);}}if(worldStop){const s=worldStop,t=s.elapsed;if(t<.6){const r=t/.6*Math.hypot(W,H);ctx.save();ctx.beginPath();ctx.arc(p.x+15-camera.x,p.y+24-camera.y,Math.max(1,r),0,TAU);ctx.clip();ctx.filter='invert(1) hue-rotate(140deg)';ctx.globalAlpha=(1-t/.6)*.8;ctx.drawImage(canvas,0,0);ctx.restore();}ctx.strokeStyle='#c9c9ee77';ctx.lineWidth=1;for(let i=0;i<12;i++){const q=i*TAU/12,r=230;line(W/2+Math.cos(q)*(r-10),H/2+Math.sin(q)*(r-10),W/2+Math.cos(q)*r,H/2+Math.sin(q)*r,'#c4c3df55',2);}ctx.textAlign='center';ctx.font='700 22px WildrootUI, WildrootUI';ctx.fillStyle='#e1ddff';ctx.fillText('정지된 세계',W/2,185);ctx.font='500 14px WildrootUI, WildrootUI';ctx.fillText(s.remaining.toFixed(1)+'초 · 잠긴 타격 '+s.hits.length,W/2,213);}if(timeRelease>0){ctx.globalAlpha=timeRelease*.35;ctx.fillStyle='#e3dbff';ctx.fillRect(0,0,W,H);}if(p.hurtImpact>0){const g=ctx.createRadialGradient(W/2,H/2,180,W/2,H/2,750);g.addColorStop(0,'#c54c3a00');g.addColorStop(1,'#d05e45'+Math.round(p.hurtImpact/.28*70).toString(16).padStart(2,'0'));ctx.fillStyle=g;ctx.fillRect(0,0,W,H);}ctx.restore();}
