function selectInteractionFocus(){const center=p.x+15,feet=p.y+p.h,candidates=[];const add=(kind,value,x,y,near)=>{if(near)candidates.push({kind,value,distance:(x-center)**2+Math.abs(y-(p.y+24))**2*.15});};for(const a of level.products||[])add('product',a,a.x,FLOOR-80,level.shop&&Math.abs(a.x-center)<76&&Math.abs(feet-FLOOR)<95);const c=level.chest;if(c)add('mask',c,c.x+23,c.opened?c.y-48:c.y+18,!c.claimed&&Math.abs(c.x+23-center)<76&&Math.abs(feet-c.y-38)<95);for(const a of level.loot||[])add('loot',a,a.x,a.y,!a.got&&Math.abs(a.x-center)<64&&Math.abs(a.y-p.y-24)<100);for(const a of level.treasures||[])add('treasure',a,a.x+21,a.y+a.h,!a.opened&&Math.abs(a.x+21-center)<65&&Math.abs(feet-a.y-a.h)<90);for(const a of level.npcs||[])add('npc',a,a.x,(a.y??FLOOR)-70,!a.hidden&&!a.rescued&&(a.sector??0)<=level.activeSector&&(!a.afterClear||level.sectors[a.sector??level.activeSector]?.cleared)&&Math.abs(a.x-center)<66&&Math.abs(feet-(a.y??FLOOR))<95);const lock=(held.has('salvage')?p.salvageHold:held.has('interact')?p.pickupHold:null)?.source;return candidates.find(a=>a.value===lock)||candidates.sort((a,b)=>a.distance-b.distance)[0]||{kind:'none',value:null};}
for(const h of Object.values(ITEMS)){if(h.effect==='manacycle')h.desc='[마법 공격용] 마법 직접 명중 시 A·S 쿨타임 0.15초, D 0.08초 회복. 발동 간격 0.65초.';if(h.effect==='moonshard')h.desc='[공용 · 물리/마법 빌드] 패링 성공 시 A·S 쿨타임 0.3초, D 1초 회복. 재발동 1초.';}

const ROAD_SERVICES={5:'broker',8:'smith',12:'cook',16:'tuner',22:'trader',26:'smith',32:'broker',36:'cook',42:'tuner',46:'trader',52:'smith',56:'cook',62:'broker',65:'tuner',67:'smith'};
const SERVICE_NPCS={broker:{name:'보석 교환상 나릴',art:0,desc:'골드 90을 보석 3개로 교환합니다. 이 만남에서는 한 번만 거래할 수 있습니다.'},smith:{name:'유산 장인 오르바',art:1,desc:'코인으로 현재 가면의 희귀도를 한 등급 올립니다. 일반→희귀→영웅이며, 보석으로 하는 기술 진화와 별개입니다.'},cook:{name:'야영 요리사 폴라',art:2,desc:'따뜻한 스튜로 체력을 35 회복합니다. 체력이 가득 차면 금화를 받지 않습니다.'},tuner:{name:'시계 조율사 테오',art:3,desc:'현재 플레이스를 지나는 동안 A·S·D 쿨타임이 8% 짧아집니다. 플레이스가 바뀌면 끝납니다.'},trader:{name:'떠돌이 상인 루핀',art:4,desc:'현재 가면에 맞는 장비를 한 개 골라 진열합니다. 먼저 물건과 가격을 살펴보고 선택하세요.'}};
function maskRarity(id,r=run){return Math.max(MASK_RARITY[id]??1,r?.maskGrades?.[id]||0);}
function npcFrame(index){return atlasCell(travelNPCImage,index,4,2,'travel-npc:'+index);}
function preCoopBuildLevel(stage){const l=preRoadBuildLevel(stage);if(!l.shop&&ROAD_SERVICES[stage]){const kind=ROAD_SERVICES[stage],d=SERVICE_NPCS[kind],s=l.sectors[0];l.npcs.push({id:'service:'+stage,service:kind,speaker:d.name,x:s.end-440,y:FLOOR,sector:0,afterClear:true,enhancedNPC:true});}for(const n of l.npcs)if(!n.marketVendor&&!n.rescue)n.enhancedNPC=true;return l;}
function pendingStoryNPC(){return(level.npcs||[]).find(n=>n.choice&&!run.story.choices[n.choice]);}
function preCoopCanExit(){return preRoadCanExit()&&!pendingStoryNPC();}
function roadNPCStep(){const n=pendingStoryNPC();if(n&&level.sectors.every(s=>s.cleared)&&!level.enemies.some(e=>!e.dead)){if(n.x<p.x-550){n.x=level.portal.x-230;n.sector=level.sectors.length-1;n.afterClear=false;}if(p.x>level.portal.x-350&&Math.abs(n.x-p.x)>100)level.storyAwaiting=n;}else level.storyAwaiting=null;}
function serviceUsed(n){return(stageState().services||[]).includes(n.id);}
function npcServiceOffer(n){const d=SERVICE_NPCS[n.service],grade=maskRarity(run.mask),base={title:d.name,desc:d.desc,price:0,allowed:true};if(n.service==='broker')return{...base,price:90};if(n.service==='smith')return{...base,price:grade===0?240:600,allowed:grade<2,desc:d.desc+'\n현재 '+FORMS[run.mask].name+' · '+RARITY[grade][0]+' → '+(RARITY[Math.min(2,grade+1)][0])+'. 등급마다 공격 피해 +4%.'};if(n.service==='cook')return{...base,price:70,allowed:p.hp<maxHP()};if(n.service==='tuner')return{...base,price:120,allowed:run.placeTuning!==journeyPlace().id};if(n.service==='trader'){const r=makeRng(level.seed+7291),pool=Object.keys(ITEMS).filter(id=>!ITEMS[id].bound&&ITEMS[id].rarity===Math.min(2,Math.floor(run.stage/25)+1)&&(ITEMS[id].affinity==='universal'||MASK_DAMAGE[run.mask].includes(ITEMS[id].affinity))),id=pool[Math.floor(r()*pool.length)];return{...base,id,price:Math.floor(ITEMS[id].price*.8),allowed:run.inventory.length<BAG_CAPACITY,desc:d.desc+'\n'+ITEMS[id].name+' · '+ITEMS[id].desc};}return base;}
function openNPC(n){if(!n.service)return preRoadOpenNPC(n);if(serviceUsed(n)){toast(n.speaker+' · 이번 만남의 거래를 마쳤습니다.');return;}const offer=npcServiceOffer(n);storyView={kind:'service',speaker:n.speaker,text:offer.desc,npc:n,offer};mode='story';screen('story');renderStory();}
function tradeNPC(n){if(mode!=='story'||storyView?.npc!==n||serviceUsed(n))return false;const offer=npcServiceOffer(n);if(!offer.allowed||run.coins<offer.price)return false;if(n.service==='trader'&&run.inventory.length>=BAG_CAPACITY)return false;run.coins-=offer.price;stageState().services=stageState().services||[];stageState().services.push(n.id);if(n.service==='broker')giveGems(3);if(n.service==='smith'){run.maskGrades=run.maskGrades||{};run.maskGrades[run.mask]=maskRarity(run.mask)+1;}if(n.service==='cook')heal(35);if(n.service==='tuner')run.placeTuning=journeyPlace().id;if(n.service==='trader')addItem(offer.id);skipStory();acquireFX(n.service==='smith'?maskRarity(run.mask):1,n.x,FLOOR-80);toast(n.speaker+' · 거래를 마쳤습니다.');updateHUD();return true;}
function renderStory(){if(storyView?.kind==='service'){const v=storyView,offer=v.offer;presentDialogue('길에서 만난 사람',v.speaker,v.text,`<button class="primary" data-npc-deal ${!offer.allowed||run.coins<offer.price?'disabled':''}>${offer.allowed?'거래한다 · '+offer.price+' G':'지금은 이용할 수 없습니다'}</button><button data-story-skip>길을 계속 간다</button>`,'보유 '+run.coins+' G · V/Enter로 글자 펼치기');}else preRoadRenderStory();$('story').dataset.dialogueKind=storyView?.kind||'';}
function drawEnhancedNPCs(){ctx.save();for(const n of level.npcs||[]){if(!n.enhancedNPC||n.hidden||n.marketVendor||(n.sector??0)>level.activeSector||n.afterClear&&!level.sectors[n.sector]?.cleared)continue;if(n.x<camera.x-100||n.x>camera.x+W+100)continue;const critical=!!n.choice&&!run.story.choices[n.choice],color=critical?'#ffe09a':n.service?'#b5ebdd':'#c6d5f5';ctx.save();ctx.filter='drop-shadow(2px 0px 0px #101723) drop-shadow(-2px 0px 0px #101723) brightness(1.15)';if(n.record){drawItemModel('utility:notebook',n.x,(n.routeFloor??FLOOR)-70,78);drawPedestal(n.x,false,72);}else{const f=npcWorldFrame(n);if(f){const h=n.service?118:108,w=f.ratio*h;ctx.drawImage(f.image,n.x-w/2,(n.routeFloor??FLOOR)-h,w,h);}}ctx.restore();const label=n.service?SERVICE_NPCS[n.service].name:n.record?'역사의 기록':n.speaker,selected=level.focusNPC===n;ctx.textAlign='center';ctx.font='700 14px WildrootUI, WildrootUI';const width=Math.max(80,ctx.measureText(label).width+22);rr(n.x-width/2,(n.routeFloor??FLOOR)-156,width,27,3,'#101b27ed',color);ctx.fillStyle=color;ctx.fillText(label,n.x,(n.routeFloor??FLOOR)-137);ctx.font='900 25px WildrootUI, WildrootUI';ctx.strokeStyle='#111a27';ctx.lineWidth=4;const mark=critical?'!':n.service?serviceUsed(n)?'✓':'◆':n.record?'▤':'…';ctx.strokeText(mark,n.x,(n.routeFloor??FLOOR)-178);ctx.fillStyle=color;ctx.fillText(mark,n.x,(n.routeFloor??FLOOR)-178);if(selected){ctx.font='700 15px WildrootUI, WildrootUI';rr(n.x-66,(n.routeFloor??FLOOR)-218,132,30,3,'#101c28f2',color);ctx.fillText('V · '+(n.service?'살펴보기':'대화·조사'),n.x,(n.routeFloor??FLOOR)-198);}}
const pending=pendingStoryNPC();if(pending&&Math.abs(pending.x-p.x)>500){const x=pending.x<p.x?camera.x+110:camera.x+W-110;rr(x-105,190+camera.y,210,35,3,'#14202af2','#e9c67f');ctx.textAlign='center';ctx.font='700 14px WildrootUI, WildrootUI';ctx.fillStyle='#f6d79d';ctx.fillText((pending.x<p.x?'← ':'')+pending.speaker+' · 중요한 대화'+(pending.x>=p.x?' →':''),x,213+camera.y);}ctx.restore();}
document.querySelector('#story-actions').addEventListener('click',e=>{if(e.target.closest('[data-npc-deal]'))tradeNPC(storyView?.npc);});

for(const d of [...Object.values(BOSS_DEFS),...Object.values(BRANCH_BOSSES)]){d.previousHP=d.hp;d.hp=Math.round(d.hp*1.3);}
function baseBossStep(e,dt){e.knockX=0;e.stun=0;e.freeze=0;const result=prePressureBaseBossStep(e,dt);if(!e.dead&&e.spec?.kind==='captain')captainPressure(e,dt);return result;}
function captainPressure(e,dt){const s=level.sectors[e.sector],phase=e.bossPhase||1,center=e.x+e.w/2,dx=p.x+15-center;e.pressureClock=(e.pressureClock||0)+dt;if(!['captainRush','captainLeap','dashAttack'].includes(e.state)){const speed=Math.abs(dx)>110?(phase>=2?230:175):Math.sin(e.pressureClock*2.3)>0?54:-54;e.x=clamp(e.x+(Math.abs(dx)>110?Math.sign(dx)*speed:speed)*dt,s.start+45,s.end-e.w-45);e.dir=Math.sign(dx)||e.dir;}e.basicPressureCD=(e.basicPressureCD??.45)-dt;if(e.basicPressureWind>0){e.basicPressureWind-=dt;if(e.basicPressureWind<=0){const dir=e.attackDir;e.attackDir=Math.sign(p.x+15-e.x-e.w/2)||e.dir;captainCut(e,phase>=2?160:138,phase>=2?23:19);e.attackDir=dir;e.basicPressureCD=phase>=2?.52:.76;e.pressureCuts=(e.pressureCuts||0)+1;}}else if(e.basicPressureCD<=0){e.basicPressureWind=phase>=2?.13:.18;e.pressureAim=Math.sign(p.x+15-e.x-e.w/2)||e.dir;}}

const COOP_STAGES={8:{name:'가면이 잠든 수문',mode:'bridge',hint:'네 힘으로 황동 레버를 당겨 줘. 나는 열린 발판을 타고 달의 봉인을 읽을게.'},12:{name:'두 사람의 물길',mode:'canals',hint:'물길이 둘로 갈라져 있어. 네가 돌판을 누르고 있으면, 내가 위쪽 수문을 열 수 있어.'},18:{name:'조약을 지키는 별자리',mode:'sequence',hint:'벽의 순서는 달, 별, 해. 높은 곳의 문양은 내가 읽을게. 아래의 무게추를 부탁해.'},25:{name:'거울꽃의 회랑',mode:'mirrors',hint:'거울을 돌리면 달빛의 방향이 바뀌어. 벽에 새긴 각도와 같은 방향으로 맞춰 보자.'}};
let coopBubbles=[];
function coopFrame(i){return atlasCell(puzzleImage,i,4,3,'puzzle:'+i);}
function coopBody(id){const q=level.puzzle;if(!q)return null;return q.active===id?p:q.bodies[id];}
function coopSay(who,text,life=5){coopBubbles=coopBubbles.filter(a=>a.who!==who);coopBubbles.push({who,text,life,max:life});}
function coopSave(){if(!level.puzzle)return;const q=level.puzzle;q.bodies[q.active]={x:p.x,y:p.y,vy:p.vy,dir:p.dir,ground:p.ground};stageState().puzzle={active:q.active,lever:q.lever,valve:!!q.valve,seals:[...q.seals],angles:[...q.angles],sequence:q.sequence,solved:q.solved,awarded:q.awarded,bodies:clone(q.bodies)};}
function validateRun(r){const c=preCoopValidateRun(r);c.riderMounted=!!r.riderMounted;for(const k of Object.keys(COOP_STAGES)){const a=r.worldState?.[k]?.puzzle;if(!a||!c.worldState[k])continue;const bodies={};for(const id of['aren','lune']){const b=a.bodies?.[id]||{};bodies[id]={x:clamp(Number.isFinite(b.x)?b.x:150,35,3150),y:clamp(Number.isFinite(b.y)?b.y:562,160,562),vy:0,dir:b.dir===-1?-1:1,ground:true};}c.worldState[k].puzzle={active:a.active==='lune'?'lune':'aren',lever:!!a.lever,valve:!!a.valve,seals:[0,1,2].map(i=>!!a.seals?.[i]),angles:[0,1,2].map(i=>clamp(Number.isInteger(a.angles?.[i])?a.angles[i]:0,0,3)),sequence:clamp(Number.isInteger(a.sequence)?a.sequence:0,0,3),solved:!!a.solved,awarded:!!a.awarded,bodies};}return c;}
function preTerrainBuildLevel(stage){const l=preCoopBuildLevel(stage),d=COOP_STAGES[stage];if(!d)return l;const saved=run.worldState?.[stage]?.puzzle;l.puzzle={...d,active:'aren',lever:false,valve:false,seals:[false,false,false],angles:[0,0,0],sequence:0,solved:false,awarded:false,bodies:{aren:{x:150,y:562,vy:0,dir:1,ground:true},lune:{x:230,y:562,vy:0,dir:1,ground:true}},...(saved?clone(saved):{}),clock:0,hold:0,plate:false,tutorial:0,said:{},idle:0};const q=l.puzzle;l.width=3200;l.title=d.name;l.kind='puzzle';l.combat=false;l.enemies=[];l.boss=null;l.miniboss=null;l.hazards=[];l.ceilings=[];l.covers=[];l.runes=[];l.coins=[];l.treasures=[];l.chest=null;l.loot=[];l.pads=[];l.props=[];l.ladders=[];l.signs=[];l.memory={x:2670,y:510,w:22,h:26};l.memoryGot=true;l.rewardSpawned=true;l.objective={kind:'puzzle',finished:!!q.solved,wave:1,total:1,timer:0};l.sectors=[{index:0,start:0,end:3200,wave:l.waveBase+1,kind:'puzzle',location:locationInfo(stage<18?'fallen-log':'sanctum-path'),spawned:true,cleared:!!q.solved&&!!run.worldState?.[stage]?.checkpoint,rewarded:true,midboss:false,timer:0}];l.activeSector=0;l.routeGroups=[{start:0,end:3200,key:stage<18?'forest':'deep'}];l.portal.x=3055;l.checkpoint.x=3084;l.plats=[makePlatform(0,FLOOR,3200,'ground',{material:stage<18?'wood':'stone'}),makePlatform(1500,505,180,'fixed',{material:'wood'}),makePlatform(1750,395,220,'fixed',{material:'stone'}),makePlatform(2020,365,210,'fixed',{material:'stone'}),makePlatform(2300,425,220,'fixed',{material:'stone'})];l.plats[1].broken=q.lever?0:999;for(const n of l.npcs){n.x=clamp(n.x,2750,2940);n.sector=0;n.afterClear=true;}l.start={x:q.bodies[q.active].x,y:q.bodies[q.active].y};return l;}
function preIntentEnterStage(stage){coopBubbles=[];preCoopEnterStage(stage);p.riderMounted=!!run.riderMounted;const q=level.puzzle;document.body.classList.toggle('coop-mode',!!q);if(q&&!q.solved){coopSay('lune',stage===8?'잠깐. 이 결계가 가면의 힘을 막고 있어. 여기서는 우리 힘으로 길을 열어야 해.':q.hint,8);q.tutorial=1;q.nextLine=stage===8?7.5:0;}}
function coopSwitch(){const q=level.puzzle;if(!q||mode!=='playing')return false;coopSave();q.active=q.active==='aren'?'lune':'aren';const b=q.bodies[q.active];Object.assign(p,{x:b.x,y:b.y,vy:b.vy||0,dir:b.dir||1,ground:b.ground,vx:0,attack:0,dash:0,rushTime:0,chargeHeld:0,jumps:0,jumpBuffer:0,platform:null});p.safe={x:b.x,y:Math.min(562,b.y)};camera.x=clamp(p.x-W*.35,0,level.width-W);q.idle=0;updateHUD();return true;}
function coopMechanism(){const q=level.puzzle;if(!q)return null;const c=p.x+15,feet=p.y+p.h;if(q.mode==='canals'&&q.seals.every(Boolean)&&!q.valve&&Math.abs(c-2670)<85&&Math.abs(feet-FLOOR)<65)return{kind:'valve',x:2670,y:FLOOR};if(Math.abs(c-570)<90&&Math.abs(feet-FLOOR)<65&&!q.lever)return{kind:'lever',x:570,y:FLOOR};for(let i=0;i<3;i++){const f=level.plats[i+2];if(Math.abs(c-(f.x+f.w*.5))<82&&Math.abs(feet-f.y)<68&&!q.seals[i])return{kind:'seal',index:i,x:f.x+f.w*.5,y:f.y};}return null;}
function coopUse(dt){const q=level.puzzle,a=coopMechanism();if(!q||!a)return false;if(a.kind==='valve'){if(q.active!=='aren'){if(pressed.has('interact'))coopSay('lune','내가 달의 돌판을 누를게. 마지막 밸브는 네 힘이 필요해.');return true;}if(held.has('interact')){q.hold+=dt;if(q.hold>=1.2){q.valve=true;q.solved=true;q.hold=0;coopSay('aren','물이 빠진다! 이제 네가 건너올 차례야.');coopSay('lune','이번엔 네가 나를 데려가 주네.',6);acquireFX(1,2670,FLOOR-65);}}else q.hold=0;return true;}if(a.kind==='lever'){if(q.active!=='aren'){if(pressed.has('interact'))coopSay('lune','너무 무거워. 아렌, 이건 네 차례야.');return true;}if(held.has('interact')){q.hold+=dt;if(q.hold>=1.2){q.lever=true;q.hold=0;level.plats[1].broken=0;acquireFX(0,570,FLOOR-70);coopSay('aren','좋아, 발판이 내려왔어. 돌판은 내가 누르고 있을게.');coopSay('lune','Tab으로 나를 불러 줘. 높은 발판은 내가 올라갈게.',7);}}else q.hold=0;return true;}if(q.active!=='lune'){if(pressed.has('interact'))coopSay('aren','이 문자는 루네가 읽을 수 있을 거야.');return true;}if(!pressed.has('interact'))return true;pressed.delete('interact');if(!q.lever){coopSay('lune','먼저 아래의 황동 레버를 열어야 해.');return true;}const i=a.index;if(q.mode==='sequence'){const order=[0,2,1];if(i!==order[q.sequence]){q.seals=[false,false,false];q.sequence=0;coopSay('lune','처음부터 다시. 달 → 별 → 해의 순서였어.');audio.tone(170,.12,'sine',.05);return true;}q.sequence++;q.seals[i]=true;}else if(q.mode==='mirrors'){q.angles[i]=(q.angles[i]+1)%4;q.seals[i]=q.angles[i]===[1,3,2][i];coopSay('lune',q.seals[i]?'빛이 다음 거울에 닿았어.':'V로 돌려서 벽에 새겨진 방향을 맞춰 보자.');}else q.seals[i]=true;acquireFX(1,a.x,a.y-45);if(q.seals.every(Boolean)){q.solved=q.mode!=='canals'||q.valve;if(q.mode==='canals'&&!q.valve){coopSay('lune','마지막 수문이 남았어. 나는 앞쪽 달의 돌판을 누를게. 아렌이 건너가서 밸브를 당겨 줘.',8);}else coopSay('lune','열렸어! 이제 너도 건너와. 함께 나가야지.',7);coopSay('aren','응. 이번 길은 네가 없으면 못 왔겠다.',6);}else if(q.seals.filter(Boolean).length===1)coopSay('lune','첫 봉인이 반응했어. 이제 돌문은 열린 채로 남아 있을 거야.');coopSave();return true;}
function worldRewardStep(dt,oldX=p.x,oldY=p.y){if(!level.puzzle)return preCoopWorldRewardStep(dt,oldX,oldY);const use=coopUse(dt),v=held.has('interact');if(use){held.delete('interact');pressed.delete('interact');}preCoopWorldRewardStep(dt,oldX,oldY);if(v)held.add('interact');}
function coopPhysics(dt){const q=level.puzzle,id=q.active==='aren'?'lune':'aren',b=q.bodies[id],oldY=b.y;b.vy=Math.min(950,(b.vy||0)+1800*dt);b.y+=b.vy*dt;b.ground=false;for(const f of level.plats)if(f.broken<=0&&b.vy>=0&&b.x+30>f.x&&b.x<f.x+f.w&&oldY+48<=f.y+10&&b.y+48>=f.y){b.y=f.y-48;b.vy=0;b.ground=true;break;}if(b.y>650){b.y=562;b.vy=0;}const aren=coopBody('aren');q.plate=!!q.lever&&Math.abs(aren.x+15-1160)<64&&Math.abs(aren.y+48-FLOOR)<25;}
function preTerrainPlayerStep(dt){const q=level.puzzle;if(!q)return preCoopPlayerStep(dt);const jump=pressed.has('jump'),beforeY=p.y,oldX=p.x,blocked=['dash','attack','skill1','skill2','ultimate','swap','parry'],restore=[];for(const a of blocked){if(held.has(a))restore.push(a);held.delete(a);pressed.delete(a);}p.attack=p.chargeHeld=0;p.inv=Math.max(1,p.inv);const bodyPhysics=FORMS[run.mask],gravity=bodyPhysics.gravity;bodyPhysics.gravity=1800;try{preCoopPlayerStep(dt);}finally{bodyPhysics.gravity=gravity;}for(const a of restore)held.add(a);if(level.puzzle!==q)return;if(jump&&p.vy<0&&p.y<=beforeY+1)p.vy=q.active==='lune'?-1180:-720;if(q.active==='lune'&&held.has('jump')&&p.vy>90)p.vy=90;coopPhysics(dt);if(q.mode==='canals'&&!q.valve){const lune=coopBody('lune');q.moonPlate=Math.abs(lune.x+15-2480)<65&&Math.abs(lune.y+48-425)<25;if(!q.moonPlate&&p.x+p.w>2550&&oldX+p.w<=2585){p.x=2550-p.w;p.vx=0;}}const open=q.plate||q.seals.some(Boolean)||q.solved;if(!open&&p.x+p.w>1400&&oldX+p.w<=1435){p.x=1400-p.w;p.vx=0;p.dash=0;}if(!q.lever)level.plats[1].broken=999;q.clock+=dt;q.idle+=dt;if(q.nextLine&&q.clock>=q.nextLine){q.nextLine=0;coopSay('lune','방향키로 이동하고 ↑/Space로 점프해. V는 장치 조작, Tab은 우리 둘 교대야. 저 레버부터 당겨 볼래?',9);}
 if(q.lever&&!q.said.plate&&Math.abs(p.x-1000)<130){q.said.plate=true;coopSay('lune','돌판을 누른 채로 있어 줘. Tab으로 바꿔도 아렌은 그 자리에서 기다려.',7);}if(q.idle>24&&!q.solved){q.idle=0;coopSay('lune',!q.lever?'황동 레버 앞에서 아렌으로 V를 잠깐 누르고 있어 봐.':!q.seals.some(Boolean)?'아렌을 돌판 위에 두고 Tab. 내 점프는 더 높고, 점프 키를 유지하면 천천히 내려와.':q.mode==='sequence'?'달은 왼쪽, 별은 오른쪽, 해는 가운데야.':q.mode==='mirrors'?'왼쪽부터 ↗, ↖, ↘ 방향으로 맞춰 봐.':'남은 달의 봉인도 V로 열어 줘.',8);}for(const b of coopBubbles)b.life-=dt;coopBubbles=coopBubbles.filter(b=>b.life>0);coopSave();}
function preTerrainEncounterStep(dt){if(!level.puzzle)return preCoopEncounterStep(dt);const q=level.puzzle,other=coopBody(q.active==='aren'?'lune':'aren');if(q.solved&&p.x>2750&&other.x>2750){level.sectors[0].cleared=true;level.objective.finished=true;level.portalOpen=true;if(!q.awarded){q.awarded=true;run.coins+=65+run.stage;giveGems(2);gainXP(90);coopSay('lune','둘 다 왔네. 결계 밖에서는 가면도 다시 빛날 거야.',6);toast('동행 퍼즐 완료 · 골드·보석·EXP 획득');coopSave();}}}
