function genericNPCIndex(name){return /기사|병사|정찰|전령|사냥/.test(name)?7:/장인|목수|대장|수리/.test(name)?1:/상인|거래|상단/.test(name)?4:/요리|식량|농부/.test(name)?2:/순례|치유|의사/.test(name)?5:/역사|기록|학자|증인/.test(name)?6:7;}
