function minibossStep(e,dt){if(worldStop)return;const before={state:e.state,wind:e.wind,spawn:e.spawnTime},phase=e.hp<e.maxHP*.45?2:1;e.knockX=0;e.stun=0;e.freeze=0;preVividMinibossStep(e,dt);if(e.dead)return;if(e.vividPhase!==phase){if(e.vividPhase){effects.push({kind:'miniImpact',art:9,x:e.x+e.w/2,y:FLOOR-70,life:.75,max:.75,r:270,dir:e.dir});impact(10);audio.tone(58,.5,'sine',.14,35);voice(e.name,'PHASE 2 · 물러설 곳은 없다.',3);}e.vividPhase=phase;}if(before.spawn>0&&e.spawnTime<=0){effects.push({kind:'miniImpact',art:9,x:e.x+e.w/2,y:FLOOR-75,life:.8,max:.8,r:215,dir:e.dir});audio.noise(.2,500,.15,70);}if(before.wind<=0&&e.wind>0){e.vividPattern=e.state;audio.tone(135,.12,'triangle',.08,75);effects.push({kind:'miniWarning',x:e.x+e.w/2,y:FLOOR-8,life:e.wind,max:e.wind,r:e.state==='forge'?260:185,dir:e.dir});}if(before.wind>0&&e.wind<=0){const art=['blink','weave'].includes(before.state)?10:before.state==='forge'?11:before.state==='cleave'?8:9;effects.push({kind:'miniImpact',art,x:e.x+e.w/2+(['cleave','rush'].includes(before.state)?e.dir*75:0),y:FLOOR-75,life:.48,max:.48,r:phase===2?245:195,dir:e.dir});impact(before.state==='forge'?10:5);audio.strike(1.1,true,false);}}
