function preMotionCastSkill(slot,swap=false){if(level?.puzzle)return false;if(run.mask!=='rider')return preIdentityCastSkill(slot,swap);if(p['skill'+slot+'CD']>0)return false;const s=maskState();if(slot===1){p.riderMounted=!p.riderMounted;run.riderMounted=p.riderMounted;s.mounted=p.riderMounted;p.rushTime=0;const batch=++fxSerial;withDamageContext('magical','rider','skill1',()=>withAttackRole('skill1',()=>areaHit(p.x+15,p.y+24,run.evolution?160:125,damage(run,'magical')*.65,'fire','skill'),[],batch));for(const e of liveTargets(p.x+15,170))if(Math.abs(e.x-p.x)<(run.evolution?160:125))withDamageContext('magical','rider','skill1',()=>applyStatus(e,'fire',run.evolution?3.8:2.8));registerSkillVisual('rider','skill1',batch,{r:125,life:.45});p.skill1CD=skillCooldown(1);audio.sfx('dash');toast(p.riderMounted?'엔진 점화 · 탑승 시간 제한 없음 · S/D 사용 가능':'하차 · 보행 모드');}else{if(!p.riderMounted){toast('S 니트로는 A로 바이크에 탄 뒤 사용할 수 있습니다.');return false;}const a=p.skill1CD,batch=++fxSerial;withDamageContext('physical','rider','skill2',()=>withAttackRole('skill2',()=>maskSkill(1),[],batch));p.skill1CD=a;p.skill2CD=skillCooldown(2);p.rushDamageType='physical';registerSkillVisual('rider','skill2',batch,{follow:true});}saveSkillCooldowns();return true;}
function castUltimate(){if(level?.puzzle)return false;if(run.mask==='rider'&&!p.riderMounted){toast('D 폭주족은 A로 바이크에 탄 뒤 사용할 수 있습니다.');return false;}return preIdentityCastUltimate();}
