function preRosterHitEnemy(e,amount,dir=1,parried=false,kind='sword',type=null){const mini=e.type==='miniboss',pattern=mini?{state:e.state,wind:e.wind,cool:e.cool,action:e.action,attackNo:e.attackNo,followup:e.followup}:null,result=preIdentityHitEnemy(e,amount,dir,parried,kind,type);if(mini&&!e.dead){e.knockX=0;e.stun=0;e.freeze=0;if(!parried)Object.assign(e,pattern);}return result;}
