function maskTick(dt){if(worldStop){const statuses=level.enemies.map(e=>[e,e.legacySlow,e.legacyCurse]);preIdentityMaskTick(dt);for(const[e,a,b]of statuses){e.legacySlow=a;e.legacyCurse=b;}}else preIdentityMaskTick(dt);if(run.mask==='rider'){run.riderMounted=!!p.riderMounted;const s=maskState();s.mounted=!!p.riderMounted;if(!p.riderMounted){s.nitro=0;if(p.rushKind==='bike')p.rushTime=0;}if(p.dash>0){s.roadTick=(s.roadTick||0)-dt;if(s.roadTick<=0){s.roadTick=.08;level.riderRoad=level.riderRoad||[];level.riderRoad.push({x:p.x+15,y:playerCombatFloor(),life:run.evolution?2.6:1.8,max:run.evolution?2.6:1.8});}}}for(const a of level.riderRoad||[]){a.life-=dt;for(const e of level.enemies)if(!e.dead&&Math.abs(e.x+e.w/2-a.x)<45&&Math.abs(e.y+e.h-a.y)<70&&!(e.roadBurnCD>0)){e.roadBurnCD=.35;withDamageContext('magical','rider','passive',()=>applyStatus(e,'fire',2.5));}}level.riderRoad=(level.riderRoad||[]).filter(a=>a.life>0);for(const e of level.enemies)e.roadBurnCD=Math.max(0,(e.roadBurnCD||0)-dt);if(run.mask==='tide'&&p.attack>0&&!p.ground&&p.vy>75)p.vy=75;}
