function rosterFrame(i){return atlasCell(rosterImage,i,4,3,'roster:'+i);}
function bossImpactFrame(i){return atlasCell(bossImpactImage,i,4,2,'bossImpact:'+i);}
function routeFloorAt(x,l=level){if(!l?.heightRoute)return FLOOR;const s=l.sectors[clamp(Math.floor(x/SECTOR_SPAN),0,l.sectors.length-1)];return x-s.start<520?s.entryFloor:s.exitFloor;}
function routeSectorExitReady(s){return !level.heightRoute||Math.abs(p.y+p.h-s.exitFloor)<145;}
