function legacyFreshRun(){return {stage:1,waveClears:0,coins:0,hp:100,energy:65,up:{vital:0,blade:0,flow:0},deaths:0,time:0,kills:0,memories:[],cleared:0,mask:'blade',artifacts:['blade','ember'],relics:[],seed:(Date.now()^Math.floor(Math.random()*0xffffffff))>>>0};}
function legacyMaxHP(r=run){return (FORMS[r.mask]?.hp||100)+Math.min(4,r.up.vital)*12;}function legacyDamage(r=run){return 22+Math.min(3,r.up.blade)*3;}
