function maskColor(){return (FORMS[run.mask]||FORMS.blade).color;}
function legacyValidateRun(r){if(!r||!Number.isInteger(r.stage)||r.stage<1||r.stage>30||!r.up||!Array.isArray(r.memories))throw Error('올바른 WILDROOT 세이브가 아닙니다.');const c=clone(r);for(const k of ['vital','blade','flow'])if(!Number.isInteger(r.up[k])||r.up[k]<0||r.up[k]>5)throw Error('강화 정보 오류');for(const k of ['coins','hp','energy','deaths','time','kills','cleared'])if(!Number.isFinite(r[k])||r[k]<0||r[k]>1e8)throw Error('저장 수치 오류');if(r.energy>100||r.cleared>30||r.memories.some(n=>!Number.isInteger(n)||n<1||n>30))throw Error('저장 범위 오류');c.up.vital=Math.min(4,c.up.vital);c.up.blade=Math.min(3,c.up.blade);c.up.flow=Math.min(3,c.up.flow);const items=r.artifacts||r.heads;c.artifacts=Array.isArray(items)&&items.length===2&&items.every(h=>FORMS[h])&&items[0]!==items[1]?[...items]:['blade','ember'];c.mask=c.artifacts.includes(r.mask)?r.mask:c.artifacts[0];c.relics=Array.isArray(r.relics)?[...new Set(r.relics.filter(k=>RELICS[k]))].slice(0,6):[];c.seed=Number.isInteger(r.seed)?r.seed>>>0:729371;if(!Array.isArray(r.relics)&&r.blessings){const total=Object.values(r.blessings).reduce((a,v)=>a+(Number.isFinite(v)?v:0),0);c.relics=['echo','conductor','mirror','froststep','counter','harvest'].slice(0,Math.min(6,Math.floor(total/5)+Number(total>0)));}delete c.blessings;delete c.heads;c.waveClears=Number.isInteger(r.waveClears)?clamp(r.waveClears,0,300):Math.max(0,(r.stage-1)*4);c.hp=clamp(c.hp,1,maxHP(c));return c;}
function preSagaValidateSave(s){if(!s||!['WILDROOT/1','WILDROOT/2','WILDROOT/3'].includes(s.format)||!Array.isArray(s.records))throw Error('WILDROOT 세이브 파일을 선택하세요.');const c=clone(s);c.checkpoint=validateRun(s.checkpoint);if(s.records.length>30||s.records.some(r=>!r||!Number.isInteger(r.stage)||r.stage<1||r.stage>30||!Number.isFinite(r.time)||r.time<0||!['S','A','B','C'].includes(r.rank)||typeof r.memory!=='boolean'))throw Error('탐험 기록 오류');if(!Number.isInteger(s.unlocked)||s.unlocked<1||s.unlocked>30)throw Error('스테이지 오류');c.format='WILDROOT/3';c.version=3;return c;}
