function spark(x,y,color,count=12,speed=180){const n=settings.reduced?Math.ceil(count*.3):count;for(let i=0;i<n;i++){const a=random(0,TAU),v=random(speed*.3,speed);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-40,life:random(.25,.65),max:.65,size:random(2,5),color});}if(particles.length>550)particles.splice(0,particles.length-550);}
function floatText(x,y,text,color='#efffc9',size=19){texts.push({x,y,text,color,life:.9,max:.9,size,vx:random(-18,18),vy:-85});if(texts.length>28)texts.shift();}

function impact(amount=6,dir=0){if(settings.shake&&!settings.reduced){shake=Math.min(20,Math.max(shake,amount));cameraPunch.x=clamp(cameraPunch.x-dir*amount*.8,-20,20);cameraPunch.y=-amount*.2;zoomPunch=Math.max(zoomPunch,Math.min(.028,amount*.0015));}}
function burst(x,y,color,r=80){effects.push({kind:'ring',x,y,color,r,life:.38,max:.38});}
function directionalSparks(x,y,color,count=20,dir=1,speed=450){for(let i=0;i<(settings.reduced?Math.ceil(count*.3):count);i++){const angle=(dir<0?Math.PI:0)+random(-1.25,1.25),v=random(speed*.35,speed),life=random(.2,.52);particles.push({x,y,px:x,py:y,vx:Math.cos(angle)*v,vy:Math.sin(angle)*v-65,life,max:life,size:random(1.5,4),color:i%4===0?'#fff8c7':color,streak:true});}if(particles.length>850)particles.splice(0,particles.length-850);}
function legacyCanExit(){return !!level?.sectors?.length&&level.sectors.every(s=>s.cleared)&&!level.enemies.some(e=>!e.dead&&e.hp>0&&e.type!=='echo');}
