 if(run.mask==='warden'){value=p.chargeHeld>0?p.chargeHeld/.9*100:p.guardMeter;label=p.chargeHeld>0?'철퇴 충전 '+Math.min(100,Math.floor(value))+'%':'수비 '+Math.floor(value)+'/100 · '+keyLabel('parry')+' 유지 방어';}
 el.style.setProperty('--trait-color',h.color);el.innerHTML=`${label}<i style="width:${clamp(value/max*100,0,100)}%"></i>`;el.title=h.passive+` · 이동 ${h.move} · 기본 체력 ${h.hp}`;
