function preSagaFormMoveSpeed(){const h=FORMS[run.mask];return h.move*(1+(p?.sagaBuff?.moon>0?.05:0))*(1+(run.training?.agility||0)*.035+gearStats().move)*(p.chargeHeld>0?(run.mask==='warden'?.35:.6):1)*(p.guard?.48:1)*(p.fortify>0?.65:1)*(run.mask==='blade'&&p.focus>=6?1.08:1);}
