let last=0,acc=0;
function frame(now){try{const dt=last?Math.min((now-last)/1000,.08):0;last=now;acc+=dt;let count=0;while(acc>=STEP&&count++<10){step(STEP);acc-=STEP;}render();requestAnimationFrame(frame);}catch(e){console.error(e);$('error-text').textContent=e.message;$('error-panel').classList.remove('hidden');}}
function fullScreen(){audio.init();if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});else $('frame').requestFullscreen?.().catch(()=>toast('이 브라우저에서는 전체화면을 사용할 수 없습니다.'));}
window.addEventListener('keydown',e=>{if(e.defaultPrevented)return;if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(mode==='story'&&['Enter','KeyV','Space'].includes(e.code)){e.preventDefault();if(!e.repeat){audio.init();advanceStory();}return;}const action=bindings[e.code];if(action){e.preventDefault();if(!physicalKeys.has(e.code)){physicalKeys.add(e.code);held.add(action);pressed.add(action);}}if(e.repeat)return;audio.init();if(mode==='story'&&['Enter','KeyV','Space'].includes(e.code)){e.preventDefault();advanceStory();return;}if(e.code==='Escape'||(!action&&e.code==='KeyP')){e.preventDefault();if(mode==='playing')pause();else if(mode==='pause')resume();else if(mode==='story')skipStory();else if(mode==='loot')closeLoot();else if(['loadout','merchant'].includes(mode))closeJourneyPanel();else if(['help','settings','records','confirm'].includes(mode))goBack();}if(!action&&e.code==='KeyB'&&['playing','loadout'].includes(mode)){e.preventDefault();if(mode==='loadout')closeJourneyPanel();else openLoadout('bag');}if(!action&&e.code==='KeyN'&&['playing','loadout'].includes(mode)){e.preventDefault();if(mode==='loadout')closeJourneyPanel();else openLoadout('growth');}if(!action&&e.code==='KeyH'&&mode==='playing')openLoadout('journal');if(!action&&e.code==='KeyM'){settings.sound=!settings.sound;saveSettings();toast(settings.sound?'음악과 효과음 켜짐':'음소거');}if(e.code==='KeyR'&&mode==='dead')retry();});
window.addEventListener('keyup',e=>{const a=bindings[e.code];if(a){physicalKeys.delete(e.code);if(!Object.entries(bindings).some(([code,act])=>act===a&&physicalKeys.has(code)))held.delete(a);}});
window.addEventListener('blur',()=>{resetInput();if(mode==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){resetInput();if(mode==='playing')pause();}});
document.querySelectorAll('[data-control]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();if(mode!=='playing')return;audio.init();b.setPointerCapture(e.pointerId);held.add(b.dataset.control);pressed.add(b.dataset.control);});for(const name of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(name,e=>{held.delete(b.dataset.control);});});
function on(id,fn){$(id).addEventListener('click',()=>{audio.init();audio.sfx('select');fn();});}
on('loot-slot0',()=>equipHead(level.chest.artifact,0));on('loot-slot1',()=>equipHead(level.chest.artifact,1));on('loot-leave',closeLoot);
on('play-btn',()=>{if(saved){previousScreen='menu';mode='confirm';screen('confirm');}else startNew();});on('confirm-new-btn',startNew);on('continue-btn',continueGame);on('pause-btn',pause);on('resume-btn',resume);on('retry-btn',retry);on('death-retry-btn',retry);on('death-checkpoint-btn',continueGame);on('to-menu-btn',menu);on('death-menu-btn',menu);on('ending-menu-btn',()=>{menu();subScreen('records');});on('next-btn',nextStage);
for(const id of ['help-btn','pause-help-btn'])on(id,()=>subScreen('help'));for(const id of ['settings-btn','pause-settings-btn'])on(id,()=>subScreen('settings'));on('stages-btn',()=>subScreen('records'));document.querySelectorAll('[data-back]').forEach(b=>b.addEventListener('click',goBack));
for(const id of ['export-btn','clear-export-btn','ending-export-btn','confirm-export-btn'])on(id,exportSave);for(const id of ['import-btn','settings-import-btn'])on(id,()=>$('save-file').click());$('save-file').addEventListener('change',e=>importSave(e.target.files[0]));
on('sound-toggle',()=>{settings.sound=!settings.sound;saveSettings();});on('shake-toggle',()=>{settings.shake=!settings.shake;saveSettings();});on('motion-toggle',()=>{settings.reduced=!settings.reduced;saveSettings();});$('volume').addEventListener('input',e=>{settings.volume=e.target.value/100;saveSettings();});$('difficulty').addEventListener('change',e=>{settings.difficulty=e.target.value;saveSettings();});on('fullscreen-btn',fullScreen);
$('reward-cards').addEventListener('click',e=>{const h=e.target.closest('[data-head]');if(h){equipHead(h.dataset.head,Number(h.dataset.slot));return;}const b=e.target.closest('[data-blessing]');if(b)claimBlessing(b.dataset.blessing);});
$('upgrade-cards').addEventListener('click',e=>{const b=e.target.closest('[data-upgrade]');if(b)buyUpgrade(b.dataset.upgrade);});$('record-chapters').addEventListener('click',e=>{const b=e.target.closest('[data-stage]');if(!b||b.disabled)return;practice=true;run=saved?clone(saved.checkpoint):freshRun();run.stage=Number(b.dataset.stage);run.hp=maxHP();run.energy=100;run.deaths=0;run.time=0;enterStage(run.stage);toast('연습 모드 · 본 여정의 체크포인트는 보존됩니다.');});
window.addEventListener('error',e=>{if(e.message){$('error-text').textContent=e.message;$('error-panel').classList.remove('hidden');}});
